      textSection = section;
    } else if (sectionName === '.data') {
      dataSection = section;
    } else if (sectionName === '.rodata') {
      rodataSection = section;
    } else if (section.type === SHT_SYMTAB) {
      symbolTableSections.push(section);
    }
