```c
FILE *fopen(const char *name, const char *mode) {
    int flags;
    char c0 = mode ? mode[0] : 'r';
    int plus = 0;
    for (const char *p = mode; p && *p; p++) if (*p == '+') plus = 1;
    switch (c0) {
    case 'r': flags = plus ? (O_RDWR) : O_RDONLY; break;
    case 'w': flags = plus ? (O_RDWR|O_CREAT|O_TRUNC) : (O_WRONLY|O_CREAT|O_TRUNC); break;
    case 'a': flags = plus ? (O_RDWR|O_CREAT|O_APPEND) : (O_WRONLY|O_CREAT|O_APPEND); break;
    default: flags = O_RDONLY; break;
    }
    int fd = my_syscall(2, (unsigned int)name, (unsigned int)flags, 0666);
    if (fd < 0) { errno = ENOENT; return NULL; }
    FILE *f = (FILE*)malloc(sizeof(FILE));
    if (!f) return NULL;  /* hmm, fd leaks; oh well */
    f->fd = fd; f->eof = 0; f->err = 0; f->name = (char*)name;
    f->append = (flags & O_APPEND);
    f->pos = f->append ? my_syscall(8, fd, 0, SEEK_END) : 0;
    return f;
}
