static void fb_uint(fbuf_t *b, unsigned long long v, int base, int upper, int neg,
                    int width, int zeropad, int left, int hash,
                    const char *extra) /* extra = "x"/"X" for hex */
{
    char num[33]; int n = 0;
    if (v == 0) num[n++] = '0';
    else while (v) { int d = (int)(v % base); num[n++] = d<10 ? '0'+d : (upper ? 'A'+d-10 : 'a'+d-10); v /= base; }
    /* reverse */
    for (int i = 0; i < n/2; i++) { char t = num[i]; num[i] = num[n-1-i]; num[n-1-i] = t; }

    char prefix[3]; int plen = 0;
    if (neg) prefix[plen++] = '-';
    if (hash && base == 16) { prefix[plen++] = '0'; prefix[plen++] = upper ? 'X' : 'x'; }
    else if (hash && base == 8 && v != 0) prefix[plen++] = '0';

    int total = plen + n;
    int pad = (width > total) ? width - total : 0;
    if (!left) {
        if (zeropad) {
            for (int i = 0; i < pad; i++) fb_putc(b, '0');
        } else {
            for (int i = 0; i < pad; i++) fb_putc(b, ' ');
        }
    }
    for (int i = 0; i < plen; i++) fb_putc(b, prefix[i]);
    for (int i = 0; i < n; i++) fb_putc(b, num[i]);
    if (left) for (int i = 0; i < pad; i++) fb_putc(b, ' ');
}
