}

static unsigned int parse_uint(const char **pp, int base)
{
    const char *p = *pp;
    unsigned int v = 0;
    int digit;

    while ((digit = (int)(unsigned char)*p) >= '0'
           && digit < '0' + base)
    {
        v = v * (unsigned int)base + (unsigned int)(digit - '0');
        p++;
    }
    *pp = p;
    return v;
}

long strtol(const char *nptr, char **endptr, int base)
{
    const char *p = nptr;
    int neg = 0;
    long v;

    while (p && *p && isspace((unsigned char)*p))
        p++;
    if (p && *p == '-')
    {
        neg = 1;
        p++;
    }
    else if (p && *p == '+')
    {
        p++;
    }
    if (base == 0)
    {
        if (p && *p == '0')
        {
            p++;
            if (*p == 'x' || *p == 'X')
            {
                p++;
                base = 16;
            }
            else
            {
                base = 8;
            }
        }
        else
        {
            base = 10;
        }
    }
    else if (base == 16 && p && *p == '0'
             && (p[1] == 'x' || p[1] == 'X'))
    {
        p += 2;
    }
    if (base < 2)
        base = 10;

    v = (long)parse_uint(&p, base);
    if (neg)
        v = -v;
    if (endptr)
        *endptr = (char *)p;
    return v;
}

unsigned long strtoul(const char *nptr, char **endptr, int base)
{
    const char *p = nptr;
    int neg = 0;
    unsigned long v;

    while (p && *p && isspace((unsigned char)*p))
        p++;
    if (p && *p == '-')
    {
        neg = 1;
        p++;
    }
    else if (p && *p == '+')
    {
        p++;
    }
    if (base == 0)
    {
        if (p && *p == '0')
        {
            p++;
            if (*p == 'x' || *p == 'X')
            {
                p++;
                base = 16;
            }
            else
            {
                base = 8;
            }
        }
        else
        {
            base = 10;
        }
    }
    else if (base == 16 && p && *p == '0'
             && (p[1] == 'x' || p[1] == 'X'))
    {
        p += 2;
    }
    if (base < 2)
        base = 10;

    v = parse_uint(&p, base);
    if (neg)
        v = (unsigned long)(0 - (long)v);
    if (endptr)
        *endptr = (char *)p;
    return v;
}

long long strtoll(const char *nptr, char **endptr, int base)
{
    /* 32-bit environment: values fit in long */
    return (long long)strtol(nptr, endptr, base);
}

