static const double __pow10tbl[] = {
    1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9
};

double atof(const char *nptr)
{
    const char *p = nptr;
    double v = 0;
    double frac = 0;
    int neg = 0;
    int have_frac = 0;
    int exp = 0;
    int negexp = 0;

    while (p && *p && isspace((unsigned char)*p))
        p++;
    if (!p || !*p)
        return 0;
    if (*p == '-')
    {
        neg = 1;
        p++;
    }
    else if (*p == '+')
    {
        p++;
    }
    while (*p >= '0' && *p <= '9')
    {
        v = v * 10.0 + (*p - '0');
        p++;
    }
    if (*p == '.')
    {
        p++;
        frac = 0.1;
        have_frac = 1;
        while (*p >= '0' && *p <= '9')
        {
            v += (*p - '0') * frac;
            frac *= 0.1;
            p++;
        }
    }
    if (*p == 'e' || *p == 'E')
    {
        p++;
        if (*p == '-')
        {
            negexp = 1;
            p++;
        }
        else if (*p == '+')
        {
            p++;
        }
        while (*p >= '0' && *p <= '9')
        {
            exp = exp * 10 + (*p - '0');
            p++;
        }
    }
    (void)have_frac;
    while (exp-- > 0 && exp < 10)
        v *= 10.0;
    if (negexp)
        while (exp-- > 0 && exp < 10)
            v /= 10.0;
    return neg ? -v : v;
}

