/* ------------------------------------------------------------------ */
/* Sorting / searching                                                 */
/* ------------------------------------------------------------------ */

static void my_qsort(void *base, size_t nmemb, size_t size,
                     int (*compar)(const void *, const void *))
{
    char *arr = (char *)base;
    int n = (int)nmemb;

    if (n < 2 || size == 0)
        return;

    /* insertion sort for small arrays */
    if (n < 16)
    {
        int i, j;
        for (i = 1; i < n; i++)
        {
            char tmp[64];
            if (size <= 64)
                memcpy(tmp, arr + i * size, size);
            else
            {
                /* fall back: use a malloc'd temp */
                char *t2 = (char *)malloc(size);
                memcpy(t2, arr + i * size, size);
                for (j = i; j > 0
                     && compar(arr + (j - 1) * size, t2) > 0; j--)
                {
                    memcpy(arr + j * size, arr + (j - 1) * size, size);
                }
                memcpy(arr + j * size, t2, size);
                free(t2);
                continue;
            }
            for (j = i; j > 0
                 && compar(arr + (j - 1) * size, tmp) > 0; j--)
            {
                memcpy(arr + j * size, arr + (j - 1) * size, size);
            }
            memcpy(arr + j * size, tmp, size);
        }
        return;
    }

    /* median-of-three quicksort */
    {
        int lo = 0, hi = n - 1;
        int mid = (lo + hi) / 2;

        /* rotate so arr[lo] <= arr[mid] <= arr[hi] */
        if (compar(arr + lo * size, arr + mid * size) > 0)
            ; /* handled below by picking median as pivot */

        /* simple recursive quicksort with median pivot */
        {
            /* pick pivot = median of lo, mid, hi */
            int p1 = lo, p2 = mid, p3 = hi;
            if (compar(arr + p2 * size, arr + p1 * size) < 0)
            {
                int t = p1; p1 = p2; p2 = t;
            }
            if (compar(arr + p3 * size, arr + p1 * size) < 0)
            {
                int t = p1; p1 = p3; p3 = t;
            }
            if (compar(arr + p3 * size, arr + p2 * size) < 0)
            {
                int t = p2; p2 = p3; p3 = t;
            }
            /* arr[p2] is the median; move it to hi-1 and use as pivot */
            char *pv = arr + (hi - 1) * size;
            char *mv = arr + p2 * size;
            if (pv != mv)
            {
                char *t = (char *)malloc(size);
                if (!t)
                    return;
                memcpy(t, pv, size);
                memcpy(pv, mv, size);
                memcpy(mv, t, size);
                free(t);
            }
            {
                const char *pivot = arr + (hi - 1) * size;
                int i = lo;
                int j = hi - 1;
                while (i < j)
                {
                    while (i < j
                           && compar(arr + i * size, pivot) <= 0)
                        i++;
                    while (j > i
                           && compar(arr + j * size, pivot) >= 0)
                        j--;
                    if (i < j)
                    {
                        char *t = (char *)malloc(size);
                        if (!t)
                            return;
                        memcpy(t, arr + i * size, size);
                        memcpy(arr + i * size, arr + j * size, size);
                        memcpy(arr + j * size, t, size);
                        free(t);
                    }
                }
                /* put pivot back in place */
                {
                    char *t = (char *)malloc(size);
                    if (!t)
                        return;
                    memcpy(t, arr + (hi - 1) * size, size);
                    memcpy(arr + (hi - 1) * size, arr + i * size, size);
                    memcpy(arr + i * size, t, size);
                    free(t);
                }
                my_qsort(arr, (size_t)i, size, compar);
                my_qsort(arr + (i + 1) * size, (size_t)(hi - i), size, compar);
            }
        }
    }
}

void qsort(void *base, size_t nmemb, size_t size,
           int (*compar)(const void *, const void *))
{
    my_qsort(base, nmemb, size, compar);
}

void *bsearch(const void *key, const void *base, size_t nmemb, size_t size,
              int (*compar)(const void *, const void *))
{
    const char *arr = (const char *)base;
    size_t lo = 0, hi = nmemb;

    while (lo < hi)
    {
        size_t mid = lo + (hi - lo) / 2;
        int c = compar(key, arr + mid * size);
        if (c == 0)
            return (void *)(arr + mid * size);
        if (c < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* String functions                                                    */
