    default:
        return "Unknown error";
    }
}

char *strchr(const char *s, int c)
{
    for (; *s; s++)
        if (*s == (char)c)
            return (char *)s;
    return *s == (char)c ? (char *)s : 0;
}

char *strrchr(const char *s, int c)
{
    const char *p = 0;
    for (;; s++)
    {
        if (*s == (char)c)
            p = s;
        if (!*s)
            return (char *)p;
    }
}

char *strstr(const char *haystack, const char *needle)
{
    size_t nl = strlen(needle);
    const char *p;

    if (nl == 0)
        return (char *)haystack;
    for (p = haystack; *p; p++)
        if (!strncmp(p, needle, nl))
            return (char *)p;
    return 0;
}

char *strpbrk(const char *s, const char *accept)
{
    const char *p;
    const char *a;
    for (p = s; *p; p++)
        for (a = accept; *a; a++)
            if (*p == *a)
                return (char *)p;
    return 0;
}

size_t strspn(const char *s, const char *accept)
{
    size_t n = 0;
    const char *a;
    while (s[n])
    {
        for (a = accept; *a; a++)
            if (s[n] == *a)
                break;
        if (!*a)
            break;
        n++;
    }
    return n;
}

size_t strcspn(const char *s, const char *reject)
{
    size_t n = 0;
    const char *a;
    while (s[n])
    {
        for (a = reject; *a; a++)
            if (s[n] == *a)
                return n;
        n++;
    }
    return n;
}

char *strtok(char *str, const char *delim)
{
    static char *save = 0;
    return strtok_r(str, delim, &save);
}

char *strtok_r(char *str, const char *delim, char **saveptr)
{
    char *s;

    if (str)
        *saveptr = str;

    s = *saveptr;
    while (*s && strpbrk(s, delim) == s)
        s++;

    if (!*s)
    {
        *saveptr = s;
        return 0;
    }

    s += strcspn(s, delim);
    if (*s)
        *saveptr = s + 1;
    else
        *saveptr = s;
    *s = 0;

    return s - strcspn(s - strcspn(s, delim), delim);
}

int strcasecmp(const char *s1, const char *s2)
{
    while (*s1 && *s2)
    {
        int c1 = tolower((unsigned char)*s1);
        int c2 = tolower((unsigned char)*s2);
        if (c1 != c2)
            return c1 - c2;
        s1++;
        s2++;
    }
    return tolower((unsigned char)*s1) - tolower((unsigned char)*s2);
}

int strncasecmp(const char *s1, const char *s2, size_t n)
{
    while (n)
    {
        int c1 = tolower((unsigned char)*s1);
        int c2 = tolower((unsigned char)*s2);
        if (c1 != c2)
            return c1 - c2;
        if (!c1)
            return 0;
        s1++;
        s2++;
        n--;
    }
    return 0;
}

char *strdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);
    if (p)
        memcpy(p, s, n);
    return p;
}

char *strndup(const char *s, size_t n)
{
    size_t len = strlen(s);
    if (len > n)
        len = n;
    char *p = (char *)malloc(len + 1);
    if (p)
    {
        memcpy(p, s, len);
        p[len] = 0;
    }
    return p;
}

/* ------------------------------------------------------------------ */
/* ctype                                                                 */
/* ------------------------------------------------------------------ */

int isspace(int c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\v'
        || c == '\f' || c == '\r';
}

int isupper(int c)
{
    return c >= 'A' && c <= 'Z';
}

int islower(int c)
{
    return c >= 'a' && c <= 'z';
}

int isalpha(int c)
{
    return isupper(c) || islower(c);
}

int isdigit(int c)
{
    return c >= '0' && c <= '9';
}

int isxdigit(int c)
{
    return isdigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

int isalnum(int c)
{
    return isalpha(c) || isdigit(c);
}

int isprint(int c)
{
    return c >= 0x20 && c <= 0x7e;
}

int ispunct(int c)
{
    return isprint(c) && !isalnum(c) && c != ' ';
}

int iscntrl(int c)
{
    return (c < 0x20 && c >= 0) || c == 0x7f;
}

int isgraph(int c)
{
    return c >= 0x21 && c <= 0x7e;
}

int tolower(int c)
{
    return isupper(c) ? c + ('a' - 'A') : c;
}

int toupper(int c)
{
    return islower(c) ? c - ('a' - 'A') : c;
}

/* ------------------------------------------------------------------ */
/* math                                                                  */
/* ------------------------------------------------------------------ */

double fabs(double x)
{
    union
    {
        double d;
        unsigned long long u;
    } u;
    u.d = x;
    u.u &= ~0x8000000000000000ULL;
    return u.d;
}

double sqrt(double x)
{
    double g;
    if (x < 0)
        return 0;
    if (x == 0)
        return 0;
    g = x > 1.0 ? x : 1.0;
    for (;;)
    {
        double ng = (g + x / g) * 0.5;
        if (ng == g)
            return ng;
        g = ng;
    }
}

double floor(double x)
{
    int i = (int)x;
    double d = (double)i;
    if (d > x)
        d -= 1.0;
    return d;
}

double ceil(double x)
{
    int i = (int)x;
    double d = (double)i;
    if (d < x)
        d += 1.0;
    return d;
}

double round(double x)
{
    return x >= 0.0 ? floor(x + 0.5) : ceil(x - 0.5);
}

double trunc(double x)
{
    return (double)(int)x;
}

double fmod(double x, double y)
{
    double r = x - y * (double)(int)(x / y);
    if (r < 0)
        r += y;
    return r;
}

double fmin(double x, double y)
{
    return x < y ? x : y;
}

double fmax(double x, double y)
{
    return x > y ? x : y;
}

double sin(double x)
{
    /* reduced-precision Taylor series; only used in rarely taken paths */
    x = fmod(x, 6.283185307179586);
    return x - x * x * x / 6.0 + x * x * x * x * x / 120.0;
}

double cos(double x)
{
    x = fmod(x + 1.5707963267948966, 6.283185307179586);
    return 1.0 - x * x / 2.0 + x * x * x * x / 24.0;
}

double tan(double x)
{
    return sin(x) / cos(x);
}

double asin(double x)
{
    return x + x * x * x / 6.0;
}

double acos(double x)
{
    return 1.5707963267948966 - x - x * x * x / 6.0;
}

double atan(double x)
{
    return x - x * x * x / 3.0 + x * x * x * x * x / 5.0;
}

double atan2(double y, double x)
{
    if (x == 0 && y == 0)
        return 0;
    if (x == 0)
        return y > 0 ? 1.5707963267948966 : -1.5707963267948966;
    if (y == 0)
        return x > 0 ? 0 : 3.141592653589793;
    return atan(y / x) + (x < 0 ? 3.141592653589793 : 0.0);
}

double exp(double x)
{
    return 1.0 + x + x * x / 2.0 + x * x * x / 6.0;
}

double log(double x)
{
    double r = 0;
    double a = x - 1.0;
    double d = a;
    int n = 1;
    if (x <= 0)
        return -INFINITY;
    while (fabs(d) > 1e-7 && n < 50)
    {
        d *= -a;
        r += d / n;
        n++;
    }
    return r;
}

double log2(double x)
{
    return log(x) * 1.4426950408889634;
}

double log10(double x)
{
    return log(x) * 4.342944819032518;
}

double pow(double base, double exponent)
{
    /* only small integer exponents are used by the doom code */
    int e = (int)exponent;
    double r = 1.0;
    if (e < 0)
        return 1.0;
    while (e-- > 0)
        r *= base;
    return r;
}

double frexp(double x, int *exponent)
{
    int e = 0;
    double r = x;
    while (r >= 1.0 && e < 100)
    {
        r *= 0.5;
        e++;
    }
    while (r < 0.5 && r != 0.0 && e > -100)
    {
        r *= 2.0;
        e--;
    }
    if (exponent)
        *exponent = e;
    return r;
}

double ldexp(double x, int exponent)
{
    double r = x;
    while (exponent-- > 0)
        r *= 2.0;
    while (exponent++ < 0)
        r *= 0.5;
    return r;
}

double modf(double value, double *integral)
{
    int i = (int)value;
    double d = (double)i;
    if (integral)
        *integral = d;
    return value - d;
}

/* ------------------------------------------------------------------ */
/* printf family                                                         */
/* ------------------------------------------------------------------ */

typedef struct
{
    char *buf;
    size_t pos;
    size_t cap;
} fbuf_t;

static void fb_putc(fbuf_t *b, char c)
{
    if (b->pos < b->cap)
        b->buf[b->pos] = c;
    b->pos++;
}

static void fb_uint(fbuf_t *b, unsigned long long v, int base, int upper,
                    int neg, int width, int zeropad, int left, int hash)
{
    char num[33];
    int n = 0;
    char prefix[3];
    int plen = 0;
    int i;

    if (v == 0)
    {
        num[n++] = '0';
    }
    else
    {
        while (v)
        {
            int d = (int)(v % (unsigned long long)base);
            num[n++] = d < 10 ? (char)('0' + d)
                              : (char)((upper ? 'A' : 'a') + d - 10);
            v /= (unsigned long long)base;
        }
        for (i = 0; i < n / 2; i++)
        {
            char t = num[i];
            num[i] = num[n - 1 - i];
            num[n - 1 - i] = t;
        }
    }

    if (neg)
        prefix[plen++] = '-';
    else if (width > 0)
        ; /* no prefix */
    if (hash && base == 16)
    {
        prefix[plen++] = '0';
        prefix[plen++] = upper ? 'X' : 'x';
    }
    else if (hash && base == 8 && v != 0)
    {
        prefix[plen++] = '0';
    }

    {
        int total = plen + n;
        int pad = (width > total) ? width - total : 0;
        if (!left)
        {
            for (i = 0; i < pad; i++)
                fb_putc(b, zeropad ? '0' : ' ');
        }
        for (i = 0; i < plen; i++)
            fb_putc(b, prefix[i]);
        for (i = 0; i < n; i++)
            fb_putc(b, num[i]);
        if (left)
            for (i = 0; i < pad; i++)
                fb_putc(b, ' ');
    }
}

static void fb_string(fbuf_t *b, const char *s, int prec, int width,
                      int left)
{
    int len;
    const char *txt;
    int i;

    if (s)
    {
        len = (int)strlen(s);
        txt = s;
    }
    else
    {
        len = 6;
        txt = "(null)";
    }
    if (prec >= 0 && len > prec)
        len = prec;
    {
        int pad = (width > len) ? width - len : 0;
        if (!left)
            for (i = 0; i < pad; i++)
                fb_putc(b, ' ');
        for (i = 0; i < len; i++)
            fb_putc(b, txt[i]);
        if (left)
            for (i = 0; i < pad; i++)
                fb_putc(b, ' ');
    }
}

static void fb_double(fbuf_t *b, double d, int prec, int width, int left,
                      int zeropad, int plus, int space)
{
    int neg = d < 0.0;
    int ip;
    double frac;
    unsigned long long fracpart = 0;
    int digits;
    char prefix[3];
    int plen = 0;
    char intbuf[32];
    int intn = 0;
    int i;
    int total;
    int pad;

    if (neg)
        d = -d;
    ip = (int)d;
    frac = d - (double)ip;

    digits = prec;
    if (prec < 0)
        digits = 6;
    for (i = 0; i < digits; i++)
    {
        if (i >= 10)
            break;
        frac *= 10.0;
        {
            int dig = (int)frac;
            frac -= (double)dig;
            fracpart = fracpart * 10 + (unsigned int)dig;
        }
    }

    if (neg)
        prefix[plen++] = '-';
    else if (plus)
        prefix[plen++] = '+';
    else if (space)
        prefix[plen++] = ' ';

    if (ip == 0)
        intbuf[intn++] = '0';
    else
    {
        int v = ip;
        while (v)
        {
            intbuf[intn++] = (char)('0' + v % 10);
            v /= 10;
        }
        for (i = 0; i < intn / 2; i++)
        {
            char t = intbuf[i];
            intbuf[i] = intbuf[intn - 1 - i];
            intbuf[intn - 1 - i] = t;
        }
    }

    total = plen + intn + (digits > 0 ? 1 + digits : 0);
    pad = (width > total) ? width - total : 0;
    if (!left)
    {
        for (i = 0; i < pad; i++)
            fb_putc(b, zeropad ? '0' : ' ');
    }
    for (i = 0; i < plen; i++)
        fb_putc(b, prefix[i]);
    for (i = 0; i < intn; i++)
        fb_putc(b, intbuf[i]);
    if (digits > 0)
    {
        fb_putc(b, '.');
        /* zero pad fracpart on the left */
        {
            int flen = 0;
            unsigned long long tmp = fracpart;
            char fbuf[16];
            int fn = 0;
            if (tmp == 0)
                fbuf[fn++] = '0';
            else
            {
                while (tmp)
                {
                    fbuf[fn++] = (char)('0' + (int)(tmp % 10));
                    tmp /= 10;
                }
                for (i = 0; i < fn / 2; i++)
                {
                    char t = fbuf[i];
                    fbuf[i] = fbuf[fn - 1 - i];
                    fbuf[fn - 1 - i] = t;
                }
            }
            flen = fn;
            for (i = flen; i < digits; i++)
                fb_putc(b, '0');
            for (i = 0; i < flen; i++)
                fb_putc(b, fbuf[i]);
        }
    }
    if (left)
        for (i = 0; i < pad; i++)
            fb_putc(b, ' ');
}

/*
 * Core format engine.  Formats into the given buffer (which must be at
 * least 1 byte; truncation is safe).
 */
static size_t my_vformat(char *out, size_t cap, const char *fmt,
                         va_list args)
{
    fbuf_t b;

    b.buf = out;
    b.pos = 0;
    b.cap = cap ? cap : 1;

    while (fmt && *fmt)
    {
        if (*fmt != '%')
        {
            fb_putc(&b, *fmt++);
            continue;
        }
        fmt++;

        {
            int left = 0, zeropad = 0, hash = 0, plus = 0, space = 0;
            int width = 0, prec = -1;
            char lenmod = 0;
            char conv;

            while (*fmt == '-' || *fmt == '+' || *fmt == ' ' || *fmt == '#'
                   || *fmt == '0')
            {
                if (*fmt == '-')
                    left = 1;
                else if (*fmt == '+')
                    plus = 1;
                else if (*fmt == ' ')
                    space = 1;
                else if (*fmt == '#')
                    hash = 1;
                else
                    zeropad = 1;
                fmt++;
            }
            if (*fmt == '*')
            {
                width = va_arg(args, int);
                fmt++;
            }
            else
            {
                while (isdigit((unsigned char)*fmt))
                {
                    width = width * 10 + (*fmt - '0');
                    fmt++;
                }
            }
            if (*fmt == '.')
            {
                fmt++;
                if (*fmt == '*')
                {
                    prec = va_arg(args, int);
                    fmt++;
                }
                else
                {
                    prec = 0;
                    while (isdigit((unsigned char)*fmt))
                    {
                        prec = prec * 10 + (*fmt - '0');
                        fmt++;
                    }
                }
            }
            if (*fmt == 'h' || *fmt == 'l' || *fmt == 'z' || *fmt == 't'
                || *fmt == 'j')
            {
                lenmod = *fmt++;
                if (lenmod == 'l' && *fmt == 'l')
                {
                    lenmod = 'L';
                    fmt++;
                }
            }
            conv = *fmt++;
            if (!fmt)
                break;

            switch (conv)
            {
            case 'd':
            case 'i':
                {
                    long long v;
                    if (lenmod == 'L')
                        v = (long long)va_arg(args, long long);
                    else if (lenmod == 'h')
                        v = (short)va_arg(args, int);
                    else
                        v = (long)va_arg(args, int);
                    if (v < 0)
                        fb_uint(&b, (unsigned long long)(-v), 10, 0, 1,
                                width, zeropad, left, 0);
                    else
                        fb_uint(&b, (unsigned long long)v, 10, 0,
                                plus ? 1 : (space && width > 0 ? 0 : 0),
                                width, zeropad, left, 0);
                }
                break;
            case 'u':
                {
                    unsigned long long v;
                    if (lenmod == 'L')
                        v = (unsigned long long)va_arg(args, unsigned long long);
                    else if (lenmod == 'h')
                        v = (unsigned short)va_arg(args, unsigned int);
                    else
                        v = (unsigned long)va_arg(args, unsigned int);
                    fb_uint(&b, v, 10, 0, 0, width, zeropad, left, 0);
                }
                break;
            case 'o':
                {
                    unsigned long long v;
                    if (lenmod == 'L')
                        v = (unsigned long long)va_arg(args, unsigned long long);
                    else
                        v = (unsigned long)va_arg(args, unsigned int);
                    fb_uint(&b, v, 8, 0, 0, width, zeropad, left, hash);
                }
                break;
            case 'x':
            case 'X':
                {
                    unsigned long long v;
                    if (lenmod == 'L')
                        v = (unsigned long long)va_arg(args, unsigned long long);
                    else
                        v = (unsigned long)va_arg(args, unsigned int);
                    fb_uint(&b, v, 16, conv == 'X', 0, width, zeropad,
                            left, hash);
                }
                break;
            case 'c':
                fb_putc(&b, (char)(unsigned char)va_arg(args, int));
                break;
            case 's':
                fb_string(&b, va_arg(args, char *), prec, width, left);
                break;
            case 'p':
                {
                    unsigned long v = (unsigned long)
                        va_arg(args, void *);
                    fb_uint(&b, v, 16, 0, 0,
                            width > 0 ? width : 8, zeropad, left, 0);
                    /* add 0x prefix properly */
                }
                break;
            case 'f':
            case 'F':
            case 'e':
            case 'E':
            case 'g':
            case 'G':
                {
                    double d = va_arg(args, double);
                    fb_double(&b, d, prec, width, left, zeropad, plus,
                              space);
                }
                break;
            case '%':
                fb_putc(&b, '%');
                break;
            case '*':
                break;
            default:
                fb_putc(&b, '%');
                fb_putc(&b, conv);
                break;
            }
        }
    }

    if (b.pos < b.cap)
        b.buf[b.pos] = 0;
    else if (b.cap)
        b.buf[b.cap - 1] = 0;

    return b.pos;
}

int vsnprintf(char *str, size_t size, const char *format, va_list args)
{
    char tmp[16384];
    size_t len;

    len = my_vformat(tmp, sizeof(tmp), format, args);
    if (str)
    {
        size_t n = len < size ? len : size;
        memcpy(str, tmp, n);
        if (size)
            str[n] = 0;
    }
    return (int)len;
}

int vprintf(const char *format, va_list args)
{
    char tmp[16384];
    size_t len = my_vformat(tmp, sizeof(tmp), format, args);
    if (len)
        write(1, tmp, len);
    return (int)len;
}

int vfprintf(FILE *stream, const char *format, va_list args)
{
    char tmp[16384];
    size_t len;
    int fd;

    if (!stream)
        stream = stderr;
    fd = stream->fd < 0 ? 2 : stream->fd;

    len = my_vformat(tmp, sizeof(tmp), format, args);
    if (len)
    {
        if (write(fd, tmp, len) < 0)
            stream->err = 1;
    }
    return (int)len;
}

int printf(const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vfprintf(stdout, format, args);
    va_end(args);
    return r;
}

int fprintf(FILE *stream, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vfprintf(stream, format, args);
    va_end(args);
    return r;
}

int sprintf(char *str, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vsnprintf(str, 16384, format, args);
    va_end(args);
    return r;
}

int snprintf(char *str, size_t size, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vsnprintf(str, size, format, args);
    va_end(args);
    return r;
}

int puts(const char *s)
{
    int len = (int)strlen(s);
    write(1, s, len);
    write(1, "\n", 1);
    return len + 1;
}

int putchar(int c)
{
    char ch = (char)c;
    write(1, &ch, 1);
    return c;
}

int putc(int c, FILE *stream)
{
    char ch = (char)c;
    if (!stream)
        stream = stdout;
    write(stream->fd, &ch, 1);
    return c;
}

int fputc(int c, FILE *stream)
{
    return putc(c, stream);
}

int fputs(const char *s, FILE *stream)
{
    int len = (int)strlen(s);
    if (!stream)
        stream = stdout;
    write(stream->fd, s, len);
    return len;
}

int getc(FILE *stream)
{
    (void)stream;
    return EOF; /* no interactive input in this environment */
}

int fgetc(FILE *stream)
{
    return getc(stream);
}

int getchar(void)
{
    return EOF; /* never read stdin: the VM's stdin is a stub */
}

int ungetc(int c, FILE *stream)
{
    (void)c;
    (void)stream;
    return EOF;
}

char *fgets(char *s, int size, FILE *stream)
{
    int i = 0;
    int c;

    if (size <= 0)
        return 0;
    for (;;)
    {
        c = getc(stream);
        if (c == EOF)
            break;
        if (i < size - 1)
            s[i++] = (char)c;
        if (c == '\n')
            break;
    }
    s[i] = 0;
    return i > 0 ? s : 0;
}

/* ------------------------------------------------------------------ */
/* stdio FILE management                                                 */
/* ------------------------------------------------------------------ */

FILE *fopen(const char *filename, const char *mode)
{
    int flags = 0;
    int plus = 0;
    char c0;
    int fd;
    FILE *f;
    const char *p;

    if (!filename)
        return 0;
    c0 = mode ? mode[0] : 'r';
    if (mode)
    {
        for (p = mode; *p; p++)
            if (*p == '+')
                plus = 1;
    }
    switch (c0)
    {
    case 'r':
        flags = plus ? O_RDWR : O_RDONLY;
        break;
    case 'w':
        flags = plus ? (O_RDWR | O_CREAT | O_TRUNC)
                     : (O_WRONLY | O_CREAT | O_TRUNC);
        break;
    case 'a':
        flags = plus ? (O_RDWR | O_CREAT | O_APPEND)
                     : (O_WRONLY | O_CREAT | O_APPEND);
        break;
    default:
        flags = O_RDONLY;
        break;
    }

    fd = open(filename, flags, 0666);
    if (fd < 0)
    {
        errno = ENOENT;
        return 0;
    }

    f = (FILE *)malloc(sizeof(FILE));
    if (!f)
    {
        close(fd);
        return 0;
    }
    f->fd = fd;
    f->eof = 0;
    f->err = 0;
    f->name = (char *)filename;
    f->append = (flags & O_APPEND) ? 1 : 0;
    f->pos = f->append ? lseek(fd, 0, SEEK_END) : 0;
    return f;
}

FILE *freopen(const char *filename, const char *mode, FILE *stream)
{
    if (stream && stream->fd >= 0)
        close(stream->fd);
    if (filename)
    {
        FILE *nf = fopen(filename, mode);
        if (nf && stream)
        {
            *stream = *nf;
            free(nf);
            return stream;
        }
        return nf;
    }
    return 0;
}

int fclose(FILE *stream)
{
    int fd;
    int r;

    if (!stream)
        return EOF;
    fd = stream->fd;
    free(stream);
    r = close(fd);
    return r < 0 ? EOF : 0;
}

int fflush(FILE *stream)
{
    (void)stream;
    return 0;
}

int setvbuf(FILE *stream, char *buf, int mode, size_t size)
{
    (void)stream;
    (void)buf;
    (void)mode;
    (void)size;
    return 0;
}

void setbuf(FILE *stream, char *buf)
{
    (void)stream;
    (void)buf;
}

int feof(FILE *stream)
{
    return stream ? stream->eof : 0;
}

int ferror(FILE *stream)
{
    return stream ? stream->err : 0;
}

void clearerr(FILE *stream)
{
    if (stream)
    {
        stream->eof = 0;
        stream->err = 0;
    }
}

int fileno(FILE *stream)
{
    return stream ? stream->fd : -1;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *stream)
{
    size_t want;
    long n;

    if (!stream || !ptr)
        return 0;
    want = size * nmemb;
    if (want == 0)
        return 0;
    if (stream->fd < 0)
        return 0;

    n = my_syscall(0, (unsigned int)stream->fd, (unsigned int)ptr,
                   (unsigned int)want, 0);
    if (n <= 0)
    {
        stream->eof = 1;
        if (n < 0)
        {
            stream->err = 1;
            errno = EIO;
        }
        return 0;
    }
    stream->pos += n;
    if (n < (long)want)
        stream->eof = 1;
    return (size_t)n / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *stream)
{
    size_t want;
    long n;

    if (!stream || !ptr)
        return 0;
    want = size * nmemb;
    if (want == 0)
        return 0;
    if (stream->fd < 0)
        return 0;

    n = my_syscall(1, (unsigned int)stream->fd, (unsigned int)ptr,
                   (unsigned int)want, 0);
    if (n < 0)
    {
        stream->err = 1;
        errno = EIO;
        return 0;
    }
    stream->pos += n;
    return (size_t)n / size;
}

int fseek(FILE *stream, long offset, int origin)
{
    long r;

    if (!stream)
        return -1;
    r = my_syscall(8, (unsigned int)stream->fd, (unsigned int)offset,
                   (unsigned int)origin, 0);
    if (r < 0)
    {
        stream->err = 1;
        return -1;
    }
    stream->pos = r;
    stream->eof = 0;
    return 0;
}

long ftell(FILE *stream)
{
    if (!stream)
        return -1;
    return stream->pos;
}

void rewind(FILE *stream)
{
    if (stream)
    {
        stream->pos = 0;
        stream->eof = 0;
        lseek(stream->fd, 0, SEEK_SET);
    }
}

int remove(const char *filename)
{
    (void)filename;
    return -1;
}

int rename(const char *oldname, const char *newname)
{
    return my_syscall(38, (unsigned int)oldname, (unsigned int)newname, 0, 0);
}

char *tmpnam(char *s)
{
    if (s)
        strcpy(s, "/tmp/doomtmp");
    return s ? s : (char *)"/tmp/doomtmp";
}

FILE *tmpfile(void)
{
    return fopen("/tmp/doomtmp", "w+");
}

/* ------------------------------------------------------------------ */
/* scanf family (minimal; only what the doom code needs)                 */
/* ------------------------------------------------------------------ */

static int my_sscanf(const char *str, const char *fmt, va_list args)
{
    int count = 0;
    int i;

    if (!str || !fmt)
        return -1;

    while (*fmt)
    {
        /* skip whitespace in format, match whitespace in input */
        if (isspace((unsigned char)*fmt))
        {
            while (*str && isspace((unsigned char)*str))
                str++;
            fmt++;
            continue;
        }
        if (*fmt != '%')
        {
            if (*str != *fmt)
                return count;
            str++;
            fmt++;
            continue;
        }
        fmt++;

        {
            int assign = 1;
            int base = 10;
            char conv;

            if (*fmt == '*')
            {
                assign = 0;
                fmt++;
            }
