/*
 * mylib.c - a small, self-contained C library for the doomgeneric MIPS build.
 *
 * Target: 32-bit little-endian MIPS (o32) ELF running inside the JavaScript
 * MIPS VM (vm.js).  The VM only provides the o32 syscalls:
 *     0 = read, 1 = write, 2 = open, 3 = close, 8 = lseek,
 *     38 = rename, 39 = mkdir, 40 = rmdir, 92 = fcntl, ...
 * There is NO brk(), NO mmap() and NO exit(), so:
 *   - malloc() works out of a static 64 MiB heap (plain BSS, which the VM
 *     treats as zero-filled memory)
 *   - all file IO goes through read/write/open/close/lseek syscalls
 *   - exit() spins forever (the VM has no way to terminate a program)
 *
 * Everything the doom code uses from libc is implemented here.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <math.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <stdarg.h>
#include <stdint.h>

int errno = 0;

/* ------------------------------------------------------------------ */
/* Syscall interface (o32: $v0 = number, $a0-$a3 = args, $v0 = result) */
/* ------------------------------------------------------------------ */

static int my_syscall(int num, unsigned int a0, unsigned int a1,
                      unsigned int a2, unsigned int a3)
{
    register unsigned int v0 asm("v0") = (unsigned int)num;
    register unsigned int r0 asm("a0") = a0;
    register unsigned int r1 asm("a1") = a1;
    register unsigned int r2 asm("a2") = a2;
    register unsigned int r3 asm("a3") = a3;

    asm volatile("syscall"
                 : "+r"(v0)
                 : "r"(r0), "r"(r1), "r"(r2), "r"(r3)
                 : "memory");
    return (int)v0;
}

/* ------------------------------------------------------------------ */
/* Heap: static 64 MiB area with a span-list allocator                 */
/* ------------------------------------------------------------------ */

#define HEAP_BYTES (64u * 1024u * 1024u)

static unsigned char __heap_area[HEAP_BYTES] __attribute__((aligned(16)));

typedef struct
{
    unsigned int start; /* in 4-byte words, offset from __heap_area */
    unsigned int len;   /* in 4-byte words */
} span_t;

#define MAX_SPANS 4096
static span_t __spans[MAX_SPANS];
static int __nspans;
static int __heap_ready;

static void __heap_init(void)
{
    if (__heap_ready)
        return;
    __heap_ready = 1;
    __spans[0].start = 0;
    __spans[0].len = HEAP_BYTES / 4;
    __nspans = 1;
}

static void __span_insert(int idx, unsigned int start, unsigned int len)
{
    int i;
    if (__nspans >= MAX_SPANS)
        return;
    for (i = __nspans; i > idx; i--)
        __spans[i] = __spans[i - 1];
    __spans[idx].start = start;
    __spans[idx].len = len;
    __nspans++;
}

static void __span_remove(int idx)
{
    int i;
    for (i = idx; i < __nspans - 1; i++)
        __spans[i] = __spans[i + 1];
    __nspans--;
}

void *malloc(size_t size)
{
    unsigned int need;
    int i;

    __heap_init();
    if (size == 0)
        size = 1;
    need = (unsigned int)((size + 15) / 16 * 4); /* 16 byte alignment */

    for (i = 0; i < __nspans; i++)
    {
        if (__spans[i].len >= need)
        {
            unsigned int rem = __spans[i].len - need;
            unsigned int start = __spans[i].start;
            if (rem >= 4)
            {
                __spans[i].len = need;
                __span_insert(i + 1, start + need, rem);
            }
            return &__heap_area[start * 4];
        }
    }
    return 0;
}

void free(void *ptr)
{
    unsigned int off;
    int i;

    if (!ptr)
        return;
    if ((unsigned char *)ptr < __heap_area
        || (unsigned char *)ptr >= __heap_area + HEAP_BYTES)
        return;

    off = ((unsigned char *)ptr - __heap_area) / 4;

    for (i = 0; i < __nspans; i++)
    {
        if (off >= __spans[i].start
            && off < __spans[i].start + __spans[i].len)
        {
            /* coalesce with following spans while adjacent */
            while (i + 1 < __nspans
                   && __spans[i].start + __spans[i].len == __spans[i + 1].start)
            {
                __spans[i].len += __spans[i + 1].len;
                __span_remove(i + 1);
            }
            /* coalesce with the previous span if adjacent */
            if (i > 0
                && __spans[i - 1].start + __spans[i - 1].len == __spans[i].start)
            {
                __spans[i - 1].len += __spans[i].len;
                __span_remove(i);
            }
            return;
        }
    }
}

void *calloc(size_t nmemb, size_t size)
{
    size_t total = nmemb * size;
    void *p = malloc(total);
    if (p)
        memset(p, 0, total);
    return p;
}

void *realloc(void *ptr, size_t size)
{
    void *np;

    if (!ptr)
        return malloc(size);
    if (size == 0)
    {
        free(ptr);
        return 0;
    }

    np = malloc(size);
    if (!np)
        return 0;

    memcpy(np, ptr, size);
    free(ptr);
    return np;
}

void *aligned_alloc(size_t alignment, size_t size)
{
    (void)alignment;
    return malloc(size);
}

void *valloc(size_t size)
{
    return malloc(size);
}

void *memalign(size_t alignment, size_t size)
{
    (void)alignment;
    return malloc(size);
}

