    long r = my_syscall(1, (unsigned int)fd, (unsigned int)buf,
                        (unsigned int)count, 0);
    if (r < 0)
    {
        errno = EIO;
        return -1;
    }
    return (ssize_t)r;
}

int close(int fd)
{
    return my_syscall(3, (unsigned int)fd, 0, 0, 0);
}

off_t lseek(int fd, off_t offset, int whence)
{
    long r = my_syscall(8, (unsigned int)fd, (unsigned int)offset,
                        (unsigned int)whence, 0);
    if (r < 0)
    {
        errno = EINVAL;
        return -1;
    }
    return (off_t)r;
}

int open(const char *pathname, int flags, ...)
{
    va_list ap;
    int mode = 0;

    va_start(ap, flags);
    mode = va_arg(ap, int);
    va_end(ap);

    return my_syscall(2, (unsigned int)pathname, (unsigned int)flags,
                      (unsigned int)mode, 0);
}

int openat(int dirfd, const char *pathname, int flags, ...)
{
    (void)dirfd;
    va_list ap;
    int mode = 0;
    va_start(ap, flags);
    mode = va_arg(ap, int);
    va_end(ap);
    return my_syscall(2, (unsigned int)pathname, (unsigned int)flags,
                      (unsigned int)mode, 0);
}

int creat(const char *pathname, mode_t mode)
{
    return my_syscall(2, (unsigned int)pathname,
                      (unsigned int)(O_WRONLY | O_CREAT | O_TRUNC),
                      (unsigned int)mode, 0);
}

int mkdir(const char *path, mode_t mode)
{
    int r = my_syscall(39, (unsigned int)path, (unsigned int)mode, 0, 0);
    if (r < 0)
        errno = EEXIST;
    return r;
}

int mkdirat(int dirfd, const char *path, mode_t mode)
{
    (void)dirfd;
    return mkdir(path, mode);
}

int rmdir(const char *path)
{
    return my_syscall(40, (unsigned int)path, 0, 0, 0);
}

int stat(const char *path, struct stat *buf)
{
    (void)path;
    if (buf)
    {
        memset(buf, 0, sizeof(*buf));
        buf->st_mode = S_IFREG | 0644;
    }
    return 0;
}

int fstat(int fd, struct stat *buf)
{
    (void)fd;
    if (buf)
    {
        memset(buf, 0, sizeof(*buf));
        buf->st_mode = S_IFREG | 0644;
    }
    return 0;
}

int lstat(const char *path, struct stat *buf)
{
    return stat(path, buf);
}

/* ------------------------------------------------------------------ */
/* Time                                                                  */
/* ------------------------------------------------------------------ */

static unsigned int __time_counter = 0;

time_t time(time_t *t)
{
    __time_counter++;
    if (t)
        *t = (time_t)__time_counter;
    return (time_t)__time_counter;
}

int gettimeofday(struct timeval *tv, void *tz)
{
    (void)tz;
    if (tv)
    {
        __time_counter++;
        tv->tv_sec = (long)__time_counter;
        tv->tv_usec = 0;
    }
    return 0;
}

int settimeofday(const struct timeval *tv, const struct timezone *tz)
{
    (void)tv;
    (void)tz;
    return -1;
}

int utimes(const char *path, void *times)
{
    (void)path;
    (void)times;
    return -1;
}

clock_t clock(void)
{
    return (clock_t)(__time_counter * 1000);
}

struct tm *gmtime(const time_t *t)
{
    static struct tm tm;
    if (!t)
        return 0;
    memset(&tm, 0, sizeof(tm));
    tm.tm_sec = (int)(*t % 60);
    tm.tm_min = (int)((*t / 60) % 60);
    tm.tm_hour = (int)((*t / 3600) % 24);
    return &tm;
}

struct tm *localtime(const time_t *t)
{
    return gmtime(t);
}

char *ctime(const time_t *t)
{
    static char buf[32];
    if (!t)
        return 0;
    snprintf(buf, sizeof(buf), "time %ld", (long)*t);
    return buf;
}

char *asctime(const struct tm *t)
{
    static char buf[32];
    if (!t)
        return 0;
    snprintf(buf, sizeof(buf), "time %d-%d-%d", t->tm_year, t->tm_mon,
             t->tm_mday);
    return buf;
}

size_t strftime(char *s, size_t max, const char *fmt, const struct tm *t)
{
    (void)fmt;
    (void)t;
    if (max)
        s[0] = 0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Numeric parsing                                                       */
/* ------------------------------------------------------------------ */

int abs(int j)
{
    return j < 0 ? -j : j;
}

long labs(long j)
{
    return j < 0 ? -j : j;
}

long long llabs(long long j)
{
    return j < 0 ? -j : j;
}

static unsigned int parse_uint(const char **pp, int base)
{
    const char *p = *pp;
    unsigned int v = 0;
    int digit;

    while ((digit = (int)(unsigned char)*p) >= '0'
           && digit < '0' + base)
    {
        v = v * (unsigned int)base + (unsigned int)(digit - '0');
        p++;
    }
    *pp = p;
    return v;
}

static int skip_hex_prefix(const char **pp)
{
    const char *p = *pp;
    if (p && p[0] == '0' && (p[1] == 'x' || p[1] == 'X'))
    {
        *pp = p + 2;
        return 1;
    }
    return 0;
}

long strtol(const char *nptr, char **endptr, int base)
{
    const char *p = nptr;
    int neg = 0;
    long v;

    while (p && *p && isspace((unsigned char)*p))
        p++;
    if (p && *p == '-')
    {
        neg = 1;
        p++;
    }
    else if (p && *p == '+')
    {
        p++;
    }
    if (base == 0)
    {
        if (p && *p == '0')
        {
            if (p[1] == 'x' || p[1] == 'X')
            {
                p += 2;
                base = 16;
            }
            else
            {
                p++;
                base = 8;
            }
        }
        else
        {
            base = 10;
        }
    }
    else if (base == 16)
    {
        skip_hex_prefix(&p);
    }
    if (base < 2)
        base = 10;

    v = (long)parse_uint(&p, base);
    if (neg)
        v = -v;
    if (endptr)
        *endptr = (char *)p;
    return v;
}

unsigned long strtoul(const char *nptr, char **endptr, int base)
{
    const char *p = nptr;
    int neg = 0;
    unsigned long v;

    while (p && *p && isspace((unsigned char)*p))
        p++;
    if (p && *p == '-')
    {
        neg = 1;
        p++;
    }
    else if (p && *p == '+')
    {
        p++;
    }
    if (base == 0)
    {
        if (p && *p == '0')
        {
            if (p[1] == 'x' || p[1] == 'X')
            {
                p += 2;
                base = 16;
            }
            else
            {
                p++;
                base = 8;
            }
        }
        else
        {
            base = 10;
        }
    }
    else if (base == 16)
    {
        skip_hex_prefix(&p);
    }
    if (base < 2)
        base = 10;

    v = parse_uint(&p, base);
    if (neg)
        v = (unsigned long)(0 - (long)v);
    if (endptr)
        *endptr = (char *)p;
    return v;
}

long long strtoll(const char *nptr, char **endptr, int base)
{
    return (long long)strtol(nptr, endptr, base);
}

unsigned long long strtoull(const char *nptr, char **endptr, int base)
{
    return (unsigned long long)strtoul(nptr, endptr, base);
}

int atoi(const char *nptr)
{
    return (int)strtol(nptr, 0, 10);
}

long atol(const char *nptr)
{
    return strtol(nptr, 0, 10);
}

double atof(const char *nptr)
{
    const char *p = nptr;
    double v = 0;
    double frac = 0;
    int neg = 0;
    int exp = 0;
    int negexp = 0;

    while (p && *p && isspace((unsigned char)*p))
        p++;
    if (!p || !*p)
        return 0;
    if (*p == '-')
    {
        neg = 1;
        p++;
    }
    else if (*p == '+')
    {
        p++;
    }
    while (*p >= '0' && *p <= '9')
    {
        v = v * 10.0 + (*p - '0');
        p++;
    }
    if (*p == '.')
    {
        p++;
        frac = 0.1;
        while (*p >= '0' && *p <= '9')
        {
            v += (*p - '0') * frac;
            frac *= 0.1;
            p++;
        }
    }
    if (*p == 'e' || *p == 'E')
    {
        p++;
        if (*p == '-')
        {
            negexp = 1;
            p++;
        }
        else if (*p == '+')
        {
            p++;
        }
        while (*p >= '0' && *p <= '9')
        {
            exp = exp * 10 + (*p - '0');
            p++;
        }
    }
    {
        int i;
        for (i = 0; i < exp && i < 10; i++)
        {
            if (negexp)
                v /= 10.0;
            else
                v *= 10.0;
        }
    }
    return neg ? -v : v;
}

static unsigned int __rand_state = 12345;

void srand(unsigned int seed)
{
    __rand_state = seed ? seed : 1;
}

int rand(void)
{
    __rand_state = __rand_state * 1103515245 + 12345;
    return (int)((__rand_state >> 16) & 0x7fff);
}

/* ------------------------------------------------------------------ */
/* Sorting / searching                                                   */
/* ------------------------------------------------------------------ */

static void my_qsort_impl(char *arr, int n, size_t size,
                          int (*compar)(const void *, const void *))
{
    int lo = 0, hi = n - 1;

    while (lo < hi)
    {
        /* insertion sort for small partitions */
        if (hi - lo < 16)
        {
            int i, j;
            for (i = lo + 1; i <= hi; i++)
            {
                char *tmp = (char *)malloc(size);
                if (!tmp)
                    return;
                memcpy(tmp, arr + i * size, size);
                for (j = i; j > lo
                     && compar(arr + (j - 1) * size, tmp) > 0; j--)
                {
                    memcpy(arr + j * size, arr + (j - 1) * size, size);
                }
                memcpy(arr + j * size, tmp, size);
                free(tmp);
            }
            return;
        }

        /* median-of-three pivot, placed at hi-1 */
        {
            int mid = (lo + hi) / 2;
            int p1 = lo, p2 = mid, p3 = hi;
            if (compar(arr + p2 * size, arr + p1 * size) < 0)
            {
                int t = p1; p1 = p2; p2 = t;
            }
            if (compar(arr + p3 * size, arr + p1 * size) < 0)
            {
                int t = p1; p1 = p3; p3 = t;
            }
            if (compar(arr + p3 * size, arr + p2 * size) < 0)
            {
                int t = p2; p2 = p3; p3 = t;
            }
            {
                char *pv = arr + (hi - 1) * size;
                char *mv = arr + p2 * size;
                if (pv != mv)
                {
                    char *t = (char *)malloc(size);
                    if (!t)
                        return;
                    memcpy(t, pv, size);
                    memcpy(pv, mv, size);
                    memcpy(mv, t, size);
                    free(t);
                }
            }
            {
                const char *pivot = arr + (hi - 1) * size;
                int i = lo;
                int j = hi - 1;
                while (i < j)
                {
                    while (i < j && compar(arr + i * size, pivot) <= 0)
                        i++;
                    while (j > i && compar(arr + j * size, pivot) >= 0)
                        j--;
                    if (i < j)
                    {
                        char *t = (char *)malloc(size);
                        if (!t)
                            return;
                        memcpy(t, arr + i * size, size);
                        memcpy(arr + i * size, arr + j * size, size);
                        memcpy(arr + j * size, t, size);
                        free(t);
                    }
                }
                {
                    char *t = (char *)malloc(size);
                    if (!t)
                        return;
                    memcpy(t, arr + (hi - 1) * size, size);
                    memcpy(arr + (hi - 1) * size, arr + i * size, size);
                    memcpy(arr + i * size, t, size);
                    free(t);
                }
                my_qsort_impl(arr, i, size, compar);
                arr += (i + 1) * size;
                lo = 0;
                hi = n - i - 2;
                n = hi + 1;
            }
        }
    }
}

void qsort(void *base, size_t nmemb, size_t size,
           int (*compar)(const void *, const void *))
{
    if (nmemb > 1 && size > 0)
        my_qsort_impl((char *)base, (int)nmemb, size, compar);
}

void *bsearch(const void *key, const void *base, size_t nmemb, size_t size,
              int (*compar)(const void *, const void *))
{
    const char *arr = (const char *)base;
    size_t lo = 0, hi = nmemb;

    while (lo < hi)
    {
        size_t mid = lo + (hi - lo) / 2;
        int c = compar(key, arr + mid * size);
        if (c == 0)
            return (void *)(arr + mid * size);
        if (c < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* String functions                                                      */
/* ------------------------------------------------------------------ */

void *memcpy(void *dest, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dest;
    const unsigned char *s = (const unsigned char *)src;
    size_t i;
    for (i = 0; i < n; i++)
        d[i] = s[i];
    return dest;
}

void *memmove(void *dest, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dest;
    const unsigned char *s = (const unsigned char *)src;
    size_t i;
    if (d > s && d < s + n)
    {
        for (i = n; i-- > 0;)
            d[i] = s[i];
    }
    else
    {
        for (i = 0; i < n; i++)
            d[i] = s[i];
    }
    return dest;
}

void *memset(void *s, int c, size_t n)
{
    unsigned char *p = (unsigned char *)s;
    size_t i;
    for (i = 0; i < n; i++)
        p[i] = (unsigned char)c;
    return s;
}

int memcmp(const void *s1, const void *s2, size_t n)
{
    const unsigned char *a = (const unsigned char *)s1;
    const unsigned char *b = (const unsigned char *)s2;
    size_t i;
    for (i = 0; i < n; i++)
    {
        if (a[i] != b[i])
            return (int)a[i] - (int)b[i];
    }
    return 0;
}

void *memchr(const void *s, int c, size_t n)
{
    const unsigned char *p = (const unsigned char *)s;
    size_t i;
    for (i = 0; i < n; i++)
        if (p[i] == (unsigned char)c)
            return (void *)(p + i);
    return 0;
}

size_t strlen(const char *s)
{
    size_t n = 0;
    while (s[n])
        n++;
    return n;
}

int strcmp(const char *s1, const char *s2)
{
    while (*s1 && *s1 == *s2)
    {
        s1++;
        s2++;
    }
    return (unsigned char)*s1 - (unsigned char)*s2;
}

int strncmp(const char *s1, const char *s2, size_t n)
{
    while (n && *s1 && *s1 == *s2)
    {
        s1++;
        s2++;
        n--;
    }
    if (n)
        return (unsigned char)*s1 - (unsigned char)*s2;
    return 0;
}

char *strcpy(char *dest, const char *src)
{
    char *d = dest;
    while ((*d++ = *src++))
        ;
    return dest;
}

char *strncpy(char *dest, const char *src, size_t n)
{
    size_t i;
    for (i = 0; i < n && src[i]; i++)
        dest[i] = src[i];
    for (; i < n; i++)
        dest[i] = 0;
    return dest;
}

char *strcat(char *dest, const char *src)
{
    char *d = dest + strlen(dest);
    while ((*d++ = *src++))
        ;
    return dest;
}

char *strncat(char *dest, const char *src, size_t n)
{
    char *d = dest + strlen(dest);
    size_t i;
    for (i = 0; i < n && src[i]; i++)
        d[i] = src[i];
    d[i] = 0;
    return dest;
}

char *strerror(int errnum)
{
    switch (errnum)
    {
    case ENOENT:
        return "No such file or directory";
    case EISDIR:
        return "Is a directory";
    case EACCES:
        return "Permission denied";
    case EEXIST:
        return "File exists";
    case EINTR:
        return "Interrupted system call";
    case EIO:
        return "I/O error";
    case ENOMEM:
        return "Not enough memory";
    case ENOSPC:
        return "No space left on device";
    case EAGAIN:
        return "Resource temporarily unavailable";
    default:
        return "Unknown error";
    }
}

char *strchr(const char *s, int c)
{
    for (;; s++)
    {
        if (*s == (char)c)
            return (char *)s;
        if (!*s)
            return 0;
    }
}

char *strrchr(const char *s, int c)
{
    const char *p = 0;
    for (;; s++)
    {
        if (*s == (char)c)
            p = s;
        if (!*s)
            return (char *)p;
    }
}

char *strstr(const char *haystack, const char *needle)
{
    size_t nl = strlen(needle);
    const char *p;

    if (nl == 0)
        return (char *)haystack;
    for (p = haystack; *p; p++)
        if (!strncmp(p, needle, nl))
            return (char *)p;
    return 0;
}

char *strpbrk(const char *s, const char *accept)
{
    const char *p;
    const char *a;
    for (p = s; *p; p++)
        for (a = accept; *a; a++)
            if (*p == *a)
                return (char *)p;
    return 0;
}

size_t strspn(const char *s, const char *accept)
{
    size_t n = 0;
    const char *a;
    while (s[n])
    {
        for (a = accept; *a; a++)
            if (s[n] == *a)
                break;
        if (!*a)
            break;
        n++;
    }
    return n;
}

size_t strcspn(const char *s, const char *reject)
{
    size_t n = 0;
    const char *a;
    while (s[n])
    {
        for (a = reject; *a; a++)
            if (s[n] == *a)
                return n;
        n++;
    }
    return n;
}

char *strtok_r(char *str, const char *delim, char **saveptr)
{
    char *s;

    if (str)
        *saveptr = str;

    s = *saveptr;

    /* skip leading delimiters */
    s += strspn(s, delim);
    if (!*s)
    {
        *saveptr = s;
        return 0;
    }

    /* end of the token */
    {
        char *end = s + strcspn(s, delim);
        *saveptr = end;
        if (*end)
            *end++ = 0;
    }
    return s;
}

char *strtok(char *str, const char *delim)
{
    static char *save = 0;
    return strtok_r(str, delim, &save);
}

int strcasecmp(const char *s1, const char *s2)
{
    while (*s1 && *s2)
    {
        int c1 = tolower((unsigned char)*s1);
        int c2 = tolower((unsigned char)*s2);
        if (c1 != c2)
            return c1 - c2;
        s1++;
        s2++;
    }
    return tolower((unsigned char)*s1) - tolower((unsigned char)*s2);
}

int strncasecmp(const char *s1, const char *s2, size_t n)
{
    while (n)
    {
        int c1 = tolower((unsigned char)*s1);
        int c2 = tolower((unsigned char)*s2);
        if (c1 != c2)
            return c1 - c2;
        if (!c1)
            return 0;
        s1++;
        s2++;
        n--;
    }
    return 0;
}

char *strdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);
    if (p)
        memcpy(p, s, n);
    return p;
}

char *strndup(const char *s, size_t n)
{
    size_t len = strlen(s);
    if (len > n)
        len = n;
    char *p = (char *)malloc(len + 1);
    if (p)
    {
        memcpy(p, s, len);
        p[len] = 0;
    }
    return p;
}

/* ------------------------------------------------------------------ */
/* ctype                                                                   */
/* ------------------------------------------------------------------ */

int isspace(int c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\v'
        || c == '\f' || c == '\r';
}

int isupper(int c)
{
    return c >= 'A' && c <= 'Z';
}

int islower(int c)
{
    return c >= 'a' && c <= 'z';
}

int isalpha(int c)
{
    return isupper(c) || islower(c);
}

int isdigit(int c)
{
    return c >= '0' && c <= '9';
}

int isxdigit(int c)
{
    return isdigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

int isalnum(int c)
{
    return isalpha(c) || isdigit(c);
}

int isprint(int c)
{
    return c >= 0x20 && c <= 0x7e;
}

int ispunct(int c)
{
    return isprint(c) && !isalnum(c) && c != ' ';
}

int iscntrl(int c)
{
    return (c >= 0 && c < 0x20) || c == 0x7f;
}

int isgraph(int c)
{
    return c >= 0x21 && c <= 0x7e;
}

int tolower(int c)
{
    return isupper(c) ? c + ('a' - 'A') : c;
}

int toupper(int c)
{
    return islower(c) ? c - ('a' - 'A') : c;
}

/* ------------------------------------------------------------------ */
/* math (integer-only arithmetic via soft-float libgcc helpers)          */
/* ------------------------------------------------------------------ */

double fabs(double x)
{
    union
    {
        double d;
        unsigned long long u;
    } u;
    u.d = x;
    u.u &= ~0x8000000000000000ULL;
    return u.d;
}

double sqrt(double x)
{
    double g;
    if (x < 0 || x == 0)
        return x == 0 ? 0 : 0;
    g = x > 1.0 ? x : 1.0;
    {
        int i;
        for (i = 0; i < 64; i++)
        {
            double ng = (g + x / g) * 0.5;
            if (ng == g)
                return ng;
            g = ng;
        }
    }
    return g;
}

double floor(double x)
{
    int i = (int)x;
    double d = (double)i;
    if (d > x)
        d -= 1.0;
    return d;
}

double ceil(double x)
{
    int i = (int)x;
    double d = (double)i;
    if (d < x)
        d += 1.0;
    return d;
}

double round(double x)
{
    return x >= 0.0 ? floor(x + 0.5) : ceil(x - 0.5);
}

double trunc(double x)
{
    return (double)(int)x;
}

double fmod(double x, double y)
{
    double r = x - y * (double)(int)(x / y);
    if (r < 0)
        r += y;
    return r;
}

double fmin(double x, double y)
{
    return x < y ? x : y;
}

double fmax(double x, double y)
{
    return x > y ? x : y;
}

double sin(double x)
{
    x = fmod(x, 6.283185307179586);
    return x - x * x * x / 6.0 + x * x * x * x * x / 120.0;
}

double cos(double x)
{
    x = fmod(x + 1.5707963267948966, 6.283185307179586);
    return 1.0 - x * x / 2.0 + x * x * x * x / 24.0;
}

double tan(double x)
{
    return sin(x) / cos(x);
}

double asin(double x)
{
    return x + x * x * x / 6.0;
}

double acos(double x)
{
    return 1.5707963267948966 - x - x * x * x / 6.0;
}

double atan(double x)
{
    return x - x * x * x / 3.0 + x * x * x * x * x / 5.0;
}

double atan2(double y, double x)
{
    if (x == 0 && y == 0)
        return 0;
    if (x == 0)
        return y > 0 ? 1.5707963267948966 : -1.5707963267948966;
    if (y == 0)
        return x > 0 ? 0 : 3.141592653589793;
    return atan(y / x) + (x < 0 ? 3.141592653589793 : 0.0);
}

double exp(double x)
{
    return 1.0 + x + x * x / 2.0 + x * x * x / 6.0;
}

double log(double x)
{
    double r = 0;
    double a;
    double d;
    int n = 1;
    if (x <= 0)
        return -INFINITY;
    a = x - 1.0;
    d = a;
    while (fabs(d) > 1e-7 && n < 50)
    {
        d *= -a;
        r += d / n;
        n++;
    }
    return r;
}

double log2(double x)
{
    return log(x) * 1.4426950408889634;
}

double log10(double x)
{
    return log(x) * 4.342944819032518;
}

double pow(double base, double exponent)
{
    int e = (int)exponent;
    double r = 1.0;
    if (e < 0)
        return 1.0;
    while (e-- > 0)
        r *= base;
    return r;
}

double frexp(double x, int *exponent)
{
    int e = 0;
    double r = x;
    while (r >= 1.0 && e < 100)
    {
        r *= 0.5;
        e++;
    }
    while (r < 0.5 && r != 0.0 && e > -100)
    {
        r *= 2.0;
        e--;
    }
    if (exponent)
        *exponent = e;
    return r;
}

double ldexp(double x, int exponent)
{
    double r = x;
    while (exponent-- > 0)
        r *= 2.0;
    while (exponent++ < 0)
        r *= 0.5;
    return r;
}

double modf(double value, double *integral)
{
    int i = (int)value;
    double d = (double)i;
    if (integral)
        *integral = d;
    return value - d;
}

/* ------------------------------------------------------------------ */
/* printf family                                                          */
/* ------------------------------------------------------------------ */

typedef struct
{
    char *buf;
    size_t pos;
    size_t cap;
} fbuf_t;

static void fb_putc(fbuf_t *b, char c)
{
    if (b->pos < b->cap)
        b->buf[b->pos] = c;
    b->pos++;
}

/*
 * Print an unsigned integer.  `sign` is one of '-', '+', ' ' or 0.
 * `hash` adds the 0x / 0 prefixes for hex/octal when set.
 */
static void fb_uint(fbuf_t *b, unsigned long long v, int base, int upper,
                    char sign, int width, int zeropad, int left, int hash)
{
    char num[33];
    int n = 0;
    char prefix[3];
    int plen = 0;
    int i;

    if (v == 0)
    {
        num[n++] = '0';
    }
    else
    {
        while (v)
        {
            int d = (int)(v % (unsigned long long)base);
            num[n++] = d < 10 ? (char)('0' + d)
                              : (char)((upper ? 'A' : 'a') + d - 10);
            v /= (unsigned long long)base;
        }
        for (i = 0; i < n / 2; i++)
        {
            char t = num[i];
            num[i] = num[n - 1 - i];
            num[n - 1 - i] = t;
        }
    }

    if (sign)
        prefix[plen++] = sign;
    if (hash && base == 16)
    {
        prefix[plen++] = '0';
        prefix[plen++] = upper ? 'X' : 'x';
    }
    else if (hash && base == 8 && v != 0)
    {
        prefix[plen++] = '0';
    }

    {
        int total = plen + n;
        int pad = (width > total) ? width - total : 0;
        if (!left)
        {
            for (i = 0; i < pad; i++)
                fb_putc(b, zeropad ? '0' : ' ');
        }
        for (i = 0; i < plen; i++)
            fb_putc(b, prefix[i]);
        for (i = 0; i < n; i++)
            fb_putc(b, num[i]);
        if (left)
            for (i = 0; i < pad; i++)
                fb_putc(b, ' ');
    }
}

static void fb_string(fbuf_t *b, const char *s, int prec, int width,
                      int left)
{
    int len;
    const char *txt;
    int i;

    if (s)
    {
        len = (int)strlen(s);
        txt = s;
    }
    else
    {
        len = 6;
        txt = "(null)";
    }
    if (prec >= 0 && len > prec)
        len = prec;
    {
        int pad = (width > len) ? width - len : 0;
        if (!left)
            for (i = 0; i < pad; i++)
                fb_putc(b, ' ');
        for (i = 0; i < len; i++)
            fb_putc(b, txt[i]);
        if (left)
            for (i = 0; i < pad; i++)
                fb_putc(b, ' ');
    }
}

static void fb_double(fbuf_t *b, double d, int prec, int width, int left,
                      int zeropad, int plus, int space)
{
    int neg = d < 0.0;
    int ip;
    double frac;
    unsigned long long fracpart = 0;
    int digits;
    char prefix[3];
    int plen = 0;
    char intbuf[32];
    int intn = 0;
    char fbuf[16];
    int fn = 0;
    int i;
    int total;
    int pad;

    if (neg)
        d = -d;
    ip = (int)d;
    frac = d - (double)ip;

    digits = prec;
    if (prec < 0)
        digits = 6;
    for (i = 0; i < digits && i < 10; i++)
    {
        frac *= 10.0;
        {
            int dig = (int)frac;
            frac -= (double)dig;
            fracpart = fracpart * 10 + (unsigned int)dig;
        }
    }

    if (neg)
        prefix[plen++] = '-';
    else if (plus)
        prefix[plen++] = '+';
    else if (space)
        prefix[plen++] = ' ';

    if (ip == 0)
        intbuf[intn++] = '0';
    else
    {
        int v = ip;
        while (v)
        {
            intbuf[intn++] = (char)('0' + v % 10);
            v /= 10;
        }
        for (i = 0; i < intn / 2; i++)
        {
            char t = intbuf[i];
            intbuf[i] = intbuf[intn - 1 - i];
            intbuf[intn - 1 - i] = t;
        }
    }

    total = plen + intn + (digits > 0 ? 1 + digits : 0);
    pad = (width > total) ? width - total : 0;
    if (!left)
    {
        for (i = 0; i < pad; i++)
            fb_putc(b, zeropad ? '0' : ' ');
    }
    for (i = 0; i < plen; i++)
        fb_putc(b, prefix[i]);
    for (i = 0; i < intn; i++)
        fb_putc(b, intbuf[i]);
    if (digits > 0)
    {
        unsigned long long tmp = fracpart;
        int flen;
        fb_putc(b, '.');
        if (tmp == 0)
            fbuf[fn++] = '0';
        else
        {
            while (tmp)
            {
                fbuf[fn++] = (char)('0' + (int)(tmp % 10));
                tmp /= 10;
            }
            for (i = 0; i < fn / 2; i++)
            {
                char t = fbuf[i];
                fbuf[i] = fbuf[fn - 1 - i];
                fbuf[fn - 1 - i] = t;
            }
        }
        flen = fn;
        for (i = flen; i < digits; i++)
            fb_putc(b, '0');
        for (i = 0; i < flen; i++)
            fb_putc(b, fbuf[i]);
    }
    if (left)
        for (i = 0; i < pad; i++)
            fb_putc(b, ' ');
}

/*
 * Core format engine.  Formats into the given buffer (truncation is
 * safe).  Returns the number of characters that would have been written.
 */
static size_t my_vformat(char *out, size_t cap, const char *fmt,
                         va_list args)
{
    fbuf_t b;

    b.buf = out;
    b.pos = 0;
    b.cap = cap ? cap : 1;

    while (fmt && *fmt)
    {
        if (*fmt != '%')
        {
            fb_putc(&b, *fmt++);
            continue;
        }
        fmt++;

        {
            int left = 0, zeropad = 0, hash = 0, plus = 0, space = 0;
            int width = 0, prec = -1;
            char lenmod = 0;
            char conv;

            while (*fmt == '-' || *fmt == '+' || *fmt == ' ' || *fmt == '#'
                   || *fmt == '0')
            {
                if (*fmt == '-')
                    left = 1;
                else if (*fmt == '+')
                    plus = 1;
                else if (*fmt == ' ')
                    space = 1;
                else if (*fmt == '#')
                    hash = 1;
                else
                    zeropad = 1;
                fmt++;
            }
            if (*fmt == '*')
            {
                width = va_arg(args, int);
                fmt++;
            }
            else
            {
                while (isdigit((unsigned char)*fmt))
                {
                    width = width * 10 + (*fmt - '0');
                    fmt++;
                }
            }
            if (*fmt == '.')
            {
                fmt++;
                if (*fmt == '*')
                {
                    prec = va_arg(args, int);
                    fmt++;
                }
                else
                {
                    prec = 0;
                    while (isdigit((unsigned char)*fmt))
                    {
                        prec = prec * 10 + (*fmt - '0');
                        fmt++;
                    }
                }
            }
            if (*fmt == 'h' || *fmt == 'l' || *fmt == 'z' || *fmt == 't'
                || *fmt == 'j')
            {
                lenmod = *fmt++;
                if (lenmod == 'l' && *fmt == 'l')
                {
                    lenmod = 'L';
                    fmt++;
                }
            }
            conv = *fmt++;
            if (!fmt)
                break;

            switch (conv)
            {
            case 'd':
            case 'i':
                {
                    long long v;
                    if (lenmod == 'L')
                        v = (long long)va_arg(args, long long);
                    else if (lenmod == 'h')
                        v = (short)va_arg(args, int);
                    else
                        v = (long)va_arg(args, int);
                    if (v < 0)
                        fb_uint(&b, (unsigned long long)(-v), 10, 0, '-',
                                width, zeropad, left, 0);
                    else
                        fb_uint(&b, (unsigned long long)v, 10, 0,
                                plus ? '+' : (space ? ' ' : 0),
                                width, zeropad, left, 0);
                }
                break;
            case 'u':
                {
                    unsigned long long v;
                    if (lenmod == 'L')
                        v = (unsigned long long)va_arg(args, unsigned long long);
                    else if (lenmod == 'h')
                        v = (unsigned short)va_arg(args, unsigned int);
                    else
                        v = (unsigned long)va_arg(args, unsigned int);
                    fb_uint(&b, v, 10, 0, 0, width, zeropad, left, 0);
                }
                break;
            case 'o':
                {
                    unsigned long long v;
                    if (lenmod == 'L')
                        v = (unsigned long long)va_arg(args, unsigned long long);
                    else
                        v = (unsigned long)va_arg(args, unsigned int);
                    fb_uint(&b, v, 8, 0, 0, width, zeropad, left, hash);
                }
                break;
            case 'x':
            case 'X':
                {
                    unsigned long long v;
                    if (lenmod == 'L')
                        v = (unsigned long long)va_arg(args, unsigned long long);
                    else
                        v = (unsigned long)va_arg(args, unsigned int);
                    fb_uint(&b, v, 16, conv == 'X', 0, width, zeropad,
                            left, hash);
                }
                break;
            case 'c':
                fb_putc(&b, (char)(unsigned char)va_arg(args, int));
                break;
            case 's':
                fb_string(&b, va_arg(args, char *), prec, width, left);
                break;
            case 'p':
                {
                    unsigned long v = (unsigned long)va_arg(args, void *);
                    fb_uint(&b, v, 16, 0, 0, width > 0 ? width : 8,
                            zeropad, left, 1);
                }
                break;
            case 'f':
            case 'F':
            case 'e':
            case 'E':
            case 'g':
            case 'G':
                {
                    double d = va_arg(args, double);
                    fb_double(&b, d, prec, width, left, zeropad, plus,
                              space);
                }
                break;
            case '%':
                fb_putc(&b, '%');
                break;
            case '*':
                break;
            default:
                fb_putc(&b, '%');
                fb_putc(&b, conv);
                break;
            }
        }
    }

    if (b.pos < b.cap)
        b.buf[b.pos] = 0;
    else if (b.cap)
        b.buf[b.cap - 1] = 0;

    return b.pos;
}

int vsnprintf(char *str, size_t size, const char *format, va_list args)
{
    static char tmp[16384];
    size_t len;

    len = my_vformat(tmp, sizeof(tmp), format, args);
    if (str)
    {
        size_t n = len < size ? len : size;
        memcpy(str, tmp, n);
        if (size)
            str[n] = 0;
    }
    return (int)len;
}

int vprintf(const char *format, va_list args)
{
    static char tmp[16384];
    size_t len = my_vformat(tmp, sizeof(tmp), format, args);
    if (len)
        write(1, tmp, len);
    return (int)len;
}

int vfprintf(FILE *stream, const char *format, va_list args)
{
    static char tmp[16384];
    size_t len;
    int fd;

    if (!stream)
        stream = stderr;
    fd = stream->fd < 0 ? 2 : stream->fd;

    len = my_vformat(tmp, sizeof(tmp), format, args);
    if (len)
    {
        if (write(fd, tmp, len) < 0)
            stream->err = 1;
    }
    return (int)len;
}

int printf(const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vfprintf(stdout, format, args);
    va_end(args);
    return r;
}

int fprintf(FILE *stream, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vfprintf(stream, format, args);
    va_end(args);
    return r;
}

int sprintf(char *str, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vsnprintf(str, 16384, format, args);
    va_end(args);
    return r;
}

int snprintf(char *str, size_t size, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = vsnprintf(str, size, format, args);
    va_end(args);
    return r;
}

int puts(const char *s)
{
    int len = (int)strlen(s);
    write(1, s, len);
    write(1, "\n", 1);
    return len + 1;
}

int putchar(int c)
{
    char ch = (char)c;
    write(1, &ch, 1);
    return c;
}

int putc(int c, FILE *stream)
{
    char ch = (char)c;
    if (!stream)
        stream = stdout;
    write(stream->fd, &ch, 1);
    return c;
}

int fputc(int c, FILE *stream)
{
    return putc(c, stream);
}

int fputs(const char *s, FILE *stream)
{
    int len = (int)strlen(s);
    if (!stream)
        stream = stdout;
    write(stream->fd, s, len);
    return len;
}

int getc(FILE *stream)
{
    (void)stream;
    return EOF; /* no interactive input in this environment */
}

int fgetc(FILE *stream)
{
    return getc(stream);
}

int getchar(void)
{
    return EOF; /* never read stdin: the VM's stdin is a stub */
}

int ungetc(int c, FILE *stream)
{
    (void)c;
    (void)stream;
    return EOF;
}

char *fgets(char *s, int size, FILE *stream)
{
    int i = 0;
    int c;

    if (size <= 0)
        return 0;
    for (;;)
    {
        c = getc(stream);
        if (c == EOF)
            break;
        if (i < size - 1)
            s[i++] = (char)c;
        if (c == '\n')
            break;
    }
    s[i] = 0;
    return i > 0 ? s : 0;
}

/* ------------------------------------------------------------------ */
/* stdio FILE management                                                 */
/* ------------------------------------------------------------------ */

FILE *fopen(const char *filename, const char *mode)
{
    int flags = 0;
    int plus = 0;
    char c0;
    int fd;
    FILE *f;
    const char *p;

    if (!filename)
        return 0;
    c0 = mode ? mode[0] : 'r';
    if (mode)
    {
        for (p = mode; *p; p++)
            if (*p == '+')
                plus = 1;
    }
    switch (c0)
    {
    case 'r':
        flags = plus ? O_RDWR : O_RDONLY;
        break;
    case 'w':
        flags = plus ? (O_RDWR | O_CREAT | O_TRUNC)
                     : (O_WRONLY | O_CREAT | O_TRUNC);
        break;
    case 'a':
        flags = plus ? (O_RDWR | O_CREAT | O_APPEND)
                     : (O_WRONLY | O_CREAT | O_APPEND);
        break;
    default:
        flags = O_RDONLY;
        break;
    }

    fd = open(filename, flags, 0666);
    if (fd < 0)
    {
        errno = ENOENT;
        return 0;
    }

    f = (FILE *)malloc(sizeof(FILE));
    if (!f)
    {
        close(fd);
        return 0;
    }
    f->fd = fd;
    f->eof = 0;
    f->err = 0;
    f->name = (char *)filename;
    f->append = (flags & O_APPEND) ? 1 : 0;
    f->pos = f->append ? lseek(fd, 0, SEEK_END) : 0;
    return f;
}

FILE *freopen(const char *filename, const char *mode, FILE *stream)
{
    if (stream && stream->fd >= 0)
        close(stream->fd);
    if (filename)
    {
        FILE *nf = fopen(filename, mode);
        if (nf && stream)
        {
            *stream = *nf;
            free(nf);
            return stream;
        }
        return nf;
    }
    return 0;
}

int fclose(FILE *stream)
{
    int fd;
    int r;

    if (!stream)
        return EOF;
    fd = stream->fd;
    free(stream);
    r = close(fd);
    return r < 0 ? EOF : 0;
}

int fflush(FILE *stream)
{
    (void)stream;
    return 0;
}

int setvbuf(FILE *stream, char *buf, int mode, size_t size)
{
    (void)stream;
    (void)buf;
    (void)mode;
    (void)size;
    return 0;
}

void setbuf(FILE *stream, char *buf)
{
    (void)stream;
    (void)buf;
}

int feof(FILE *stream)
{
    return stream ? stream->eof : 0;
}

int ferror(FILE *stream)
{
    return stream ? stream->err : 0;
}

void clearerr(FILE *stream)
{
    if (stream)
    {
        stream->eof = 0;
        stream->err = 0;
    }
}

int fileno(FILE *stream)
{
    return stream ? stream->fd : -1;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *stream)
{
    size_t want;
    long n;

    if (!stream || !ptr)
        return 0;
    want = size * nmemb;
    if (want == 0)
        return 0;
    if (stream->fd < 0)
        return 0;

    n = my_syscall(0, (unsigned int)stream->fd, (unsigned int)ptr,
                   (unsigned int)want, 0);
    if (n <= 0)
    {
        stream->eof = 1;
        if (n < 0)
        {
            stream->err = 1;
            errno = EIO;
        }
        return 0;
    }
    stream->pos += n;
    if (n < (long)want)
        stream->eof = 1;
    return (size_t)n / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *stream)
{
    size_t want;
    long n;

    if (!stream || !ptr)
        return 0;
    want = size * nmemb;
    if (want == 0)
        return 0;
    if (stream->fd < 0)
        return 0;

    n = my_syscall(1, (unsigned int)stream->fd, (unsigned int)ptr,
                   (unsigned int)want, 0);
    if (n < 0)
    {
        stream->err = 1;
        errno = EIO;
        return 0;
    }
    stream->pos += n;
    return (size_t)n / size;
}

int fseek(FILE *stream, long offset, int origin)
{
    long r;

    if (!stream)
        return -1;
    r = my_syscall(8, (unsigned int)stream->fd, (unsigned int)offset,
                   (unsigned int)origin, 0);
    if (r < 0)
    {
        stream->err = 1;
        return -1;
    }
    stream->pos = r;
    stream->eof = 0;
    return 0;
}

long ftell(FILE *stream)
{
    if (!stream)
        return -1;
    return stream->pos;
}

void rewind(FILE *stream)
{
    if (stream)
    {
        stream->pos = 0;
        stream->eof = 0;
        lseek(stream->fd, 0, SEEK_SET);
    }
}

int remove(const char *filename)
{
    (void)filename;
    return -1;
}

int rename(const char *oldname, const char *newname)
{
    return my_syscall(38, (unsigned int)oldname, (unsigned int)newname, 0, 0);
}

char *tmpnam(char *s)
{
    if (s)
        strcpy(s, "/tmp/doomtmp");
    return s ? s : (char *)"/tmp/doomtmp";
}

FILE *tmpfile(void)
{
    return fopen("/tmp/doomtmp", "w+");
}

/* ------------------------------------------------------------------ */
/* scanf family (minimal; covers what the doom code needs)               */
/* ------------------------------------------------------------------ */

static int my_sscanf(const char *str, const char *fmt, va_list args)
{
    int count = 0;

    if (!str || !fmt)
        return -1;

    while (*fmt)
    {
        if (isspace((unsigned char)*fmt))
        {
            while (*str && isspace((unsigned char)*str))
                str++;
            fmt++;
            continue;
        }
        if (*fmt != '%')
        {
            if (*str != *fmt)
                return count;
            str++;
            fmt++;
            continue;
        }
        fmt++;

        {
            int assign = 1;
            char conv;

            if (*fmt == '*')
            {
                assign = 0;
                fmt++;
            }
            while (*fmt == 'l' || *fmt == 'h' || *fmt == 'z')
                fmt++;
            conv = *fmt++;
            if (!fmt)
                break;

            switch (conv)
            {
            case 'd':
            case 'i':
                {
                    int v = 0;
                    int neg = 0;
                    if (*str == '-')
                    {
                        neg = 1;
                        str++;
                    }
                    while (isdigit((unsigned char)*str))
                    {
                        v = v * 10 + (*str - '0');
                        str++;
                    }
                    if (neg)
                        v = -v;
                    if (assign)
                    {
                        *va_arg(args, int *) = v;
                        count++;
                    }
                }
                break;
            case 'u':
                {
                    int v = 0;
                    while (isdigit((unsigned char)*str))
                    {
                        v = v * 10 + (*str - '0');
                        str++;
                    }
                    if (assign)
                    {
                        *va_arg(args, int *) = v;
                        count++;
                    }
                }
                break;
            case 'x':
            case 'X':
                {
                    int v = 0;
                    if (str[0] == '0' && (str[1] == 'x' || str[1] == 'X'))
                        str += 2;
                    while (isxdigit((unsigned char)*str))
                    {
                        int d = (int)(unsigned char)*str;
                        d = d - (d >= 'a' ? 87 : (d >= 'A' ? 55 : 0));
                        v = v * 16 + d;
                        str++;
                    }
                    if (assign)
                    {
                        *va_arg(args, int *) = v;
                        count++;
                    }
                }
                break;
            case 'o':
                {
                    int v = 0;
                    while (*str >= '0' && *str <= '7')
                    {
                        v = v * 8 + (*str - '0');
                        str++;
                    }
                    if (assign)
                    {
                        *va_arg(args, int *) = v;
                        count++;
                    }
                }
                break;
            case 'c':
                if (assign)
                {
                    *va_arg(args, int *) = *str ? *str : '\0';
                    str++;
                    count++;
                }
                break;
            case 's':
                {
                    char *dst = va_arg(args, char *);
                    if (assign && dst)
                    {
                        while (*str && !isspace((unsigned char)*str))
                            *dst++ = *str++;
                        *dst = 0;
                        count++;
                    }
                    else
                    {
                        while (*str && !isspace((unsigned char)*str))
                            str++;
                    }
                }
                break;
            case 'f':
                {
                    double v = atof(str);
                    while (isdigit((unsigned char)*str) || *str == '.')
                        str++;
                    if (assign)
                    {
                        *va_arg(args, double *) = v;
                        count++;
                    }
                }
                break;
            case '%':
                if (*str != '%')
                    return count;
                str++;
                break;
            default:
                return count;
            }
        }
    }

    return count;
}

int sscanf(const char *str, const char *format, ...)
{
    va_list args;
    int r;
    va_start(args, format);
    r = my_sscanf(str, format, args);
    va_end(args);
    return r;
}

int scanf(const char *format, ...)
{
    (void)format;
    return EOF;
}

int fscanf(FILE *stream, const char *format, ...)
{
    (void)stream;
    (void)format;
    return EOF;
}

