/*
 * mylib_fp.c - software IEEE-754 floating point helpers for the MIPS VM.
 *
 * Debian's cross libgcc.a is built with the HARD float ABI (its __adddf3
 * & friends contain COP1 instructions like `add.d $f0,$f12,$f14`), which
 * the JavaScript VM cannot execute.  So we provide every soft-float
 * helper the compiler may reference, implemented in pure integer code.
 *
 * The doom code itself barely uses floating point (one fabs() on a path
 * that is short-circuited, plus a few double constants), so these helpers
 * are mostly defensive; still they implement correct round-to-nearest-even
 * binary64 semantics.
 */

#include <stdint.h>

/* ------------------------------------------------------------------ */
/* bit-level view of a double                                          */
/* ------------------------------------------------------------------ */

typedef struct
{
    unsigned int sign;
    int exp;              /* biased exponent (0..2047) */
    uint64_t frac;        /* 52-bit fraction (implicit bit NOT included) */
} df_t;

static df_t df_unpack(uint64_t v)
{
    df_t d;
    d.sign = (v >> 63) & 1;
    d.exp = (int)((v >> 52) & 0x7FF);
    d.frac = v & 0x000FFFFFFFFFFFFFULL;
    return d;
}

static uint64_t df_pack(df_t d)
{
    return (d.sign << 63) | ((uint64_t)d.exp << 52) | d.frac;
}

/* 53-bit significand including the implicit bit */
static uint64_t df_sig(df_t d)
{
    return d.frac | (d.exp ? 0x0010000000000000ULL : 0);
}

static int df_is_zero(df_t d)
{
    return d.exp == 0 && d.frac == 0;
}

/*
 * Expand a subnormal to a normal representation: the value is
 * frac * 2^-1074.  We shift the fraction left until the implicit bit
 * is set and lower the exponent accordingly (exp becomes 1 - k).
 */
static void df_normalize_subnormal(df_t *d)
{
    int shift;

    if (d->exp != 0 || d->frac == 0)
        return;
    shift = 0;
    while (!(d->frac & 0x0010000000000000ULL))
    {
        d->frac <<= 1;
        shift++;
        if (shift > 64)
        {
            d->frac = 0;
            d->exp = 0;
            return;
        }
    }
    d->exp = 1 - shift;
}

/* ------------------------------------------------------------------ */
/* 128-bit multiply of two 64-bit values (for internal math)           */
/* ------------------------------------------------------------------ */

typedef struct
{
    uint64_t hi;
    uint64_t lo;
} u128_t;

static u128_t mul128(uint64_t a, uint64_t b)
{
    u128_t r;
    uint64_t a_lo = a & 0xFFFFFFFFULL;
    uint64_t a_hi = a >> 32;
    uint64_t b_lo = b & 0xFFFFFFFFULL;
    uint64_t b_hi = b >> 32;

    uint64_t p0 = a_lo * b_lo;
    uint64_t p1 = a_lo * b_hi;
    uint64_t p2 = a_hi * b_lo;
    uint64_t p3 = a_hi * b_hi;

    uint64_t mid = (p0 >> 32) + (p1 & 0xFFFFFFFFULL) + (p2 & 0xFFFFFFFFULL);

    r.lo = (mid << 32) | (p0 & 0xFFFFFFFFULL);
    r.hi = p3 + (p1 >> 32) + (p2 >> 32) + (mid >> 32);
    return r;
}

/* 128 by 64 division returning a 64-bit quotient (long division) */
static uint64_t div128_64(uint64_t hi, uint64_t lo, uint64_t d)
{
    uint64_t q = 0;
    uint64_t rem = 0;
    int i;

    if (d == 0)
        return 0;
    for (i = 63; i >= 0; i--)
    {
        rem = (rem << 1) | ((hi >> i) & 1);
        if (rem >= d)
        {
            rem -= d;
            q |= 1ULL << i;
            continue;
        }
        rem = (rem << 1) | ((lo >> i) & 1);
        if (rem >= d)
        {
            rem -= d;
            q |= 1ULL << i;
        }
    }
    return q;
}

/* 128-bit compare */
static int cmp128(uint64_t ahi, uint64_t alo, uint64_t bhi, uint64_t blo)
{
    if (ahi != bhi)
        return ahi < bhi ? -1 : 1;
    if (alo != blo)
        return alo < blo ? -1 : 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* double add / sub                                                    */
/* ------------------------------------------------------------------ */

static uint64_t df_add(uint64_t a_in, uint64_t b_in, int sub)
{
    df_t a, b, r;

    if (sub)
        b_in ^= (1ULL << 63);

    a = df_unpack(a_in);
    b = df_unpack(b_in);

    if (df_is_zero(a))
        return b_in;
    if (df_is_zero(b))
        return a_in;

    df_normalize_subnormal(&a);
    df_normalize_subnormal(&b);

    if (a.sign != b.sign)
    {
        /* subtraction: make b = -b and fall through to addition */
        b.sign = a.sign;
    }

    /* align b to a's exponent */
    if (a.exp < b.exp)
    {
        uint64_t t = a_in;
        a_in = b_in;
        b_in = t;
        a = df_unpack(a_in);
        b = df_unpack(b_in);
    }

    {
        int diff = a.exp - b.exp;
        uint64_t sa = df_sig(a);
        uint64_t sb = df_sig(b);
        uint64_t sig;
        int e = a.exp;
        uint64_t dropped = 0;
        int has_dropped = 0;

        if (diff > 64)
        {
            /* b is negligible; result is a (exact enough) */
            return a_in;
        }
        if (diff > 0)
        {
            dropped = (sb >> (diff - 1)) & 1;      /* guard bit */
            if (diff >= 2)
                dropped |= (sb >> (diff - 2)) & 1; /* round bit */
            dropped |= sb & (((uint64_t)1 << (diff < 64 ? diff - 1 : 63)) - 1);
            sb >>= diff;
            has_dropped = 1;
        }
        else if (diff == 0)
        {
            has_dropped = 0;
        }
        else
        {
            /* a is subnormal relative: shift a right */
            int d = -diff;
            uint64_t aa = sa;
            dropped = (aa >> (d - 1)) & 1;
            if (d >= 2)
                dropped |= (aa >> (d - 2)) & 1;
            dropped |= aa & (((uint64_t)1 << (d < 64 ? d - 1 : 63)) - 1);
            aa >>= d;
            sig = aa + sb;
            e = b.exp;
            /* continue to rounding with sig/e as computed */
            goto rounding;
        }

        sig = sa + sb;

        /* normalize: sig may have the carry bit (bit 53) */
        if (sig & 0x0020000000000000ULL)
        {
            sig >>= 1;
            e++;
            if (has_dropped)
                dropped >>= 1;
        }

    rounding:
        /* round to nearest, ties to even (dropped is 0 or nonzero) */
        if (has_dropped && (dropped & 1)
            && ((dropped >> 1) || (sig & 1)))
        {
            sig++;
            if (sig & 0x0020000000000000ULL)
            {
                sig >>= 1;
                e++;
            }
        }
        /* truncate to 52 fraction bits */
        {
            uint64_t frac = (sig >> 1) & 0x000FFFFFFFFFFFFFULL;
            int implicit = (sig >> 52) & 1;
            (void)implicit;
            r.frac = frac;
            r.exp = e;
        }

        if (r.exp <= 0)
        {
            /* (sub)normal result: shift fraction right */
            int sh = 1 - r.exp;
            if (sh >= 64)
            {
                r.frac = 0;
                r.exp = 0;
            }
            else
            {
                r.frac >>= sh;
                r.exp = 0;
            }
        }
        else if (r.exp >= 2047)
        {
            /* overflow -> infinity */
            r.exp = 2047;
            r.frac = 0;
        }
    }

    r.sign = a.sign;
    return df_pack(r);
}

uint64_t __adddf3(double a, double b)
{
    union
    {
        double d;
        uint64_t u;
    } ua, ub;
    ua.d = a;
    ub.d = b;
    return (uint64_t)(double)df_add(ua.u, ub.u, 0);
}

uint64_t __subdf3(double a, double b)
{
    union
    {
        double d;
        uint64_t u;
    } ua, ub;
    ua.d = a;
    ub.d = b;
    return (uint64_t)(double)df_add(ua.u, ub.u, 1);
}

uint64_t __negdf2(double a)
{
    union
    {
        double d;
        uint64_t u;
    } u;
    u.d = a;
    u.u ^= (1ULL << 63);
    return (uint64_t)u.d;
}

uint64_t __absdf2(double a)
{
    union
    {
        double d;
        uint64_t u;
    } u;
    u.d = a;
    u.u &= 0x7FFFFFFFFFFFFFULL;
    return (uint64_t)u.d;
}

/* ------------------------------------------------------------------ */
/* double multiply                                                     */
/* ------------------------------------------------------------------ */

uint64_t __muldf3(double a, double b)
{
    union
    {
        double d;
        uint64_t u;
    } ua, ub;
    df_t da, db, r;
    u128_t p;

    ua.d = a;
    ub.d = b;
    da = df_unpack(ua.u);
    db = df_unpack(ub.u);

    if (df_is_zero(da) || df_is_zero(db))
    {
        /* 0 * x (including 0 * inf = NaN in IEEE; keep it simple) */
        r.sign = da.sign ^ db.sign;
        r.exp = 0;
        r.frac = 0;
        if (!df_is_zero(da) || !df_is_zero(db))
        {
            /* non-finite involved: return NaN */
            r.exp = 2047;
            r.frac = 1;
        }
        return (uint64_t)(double)df_pack(r);
    }

    df_normalize_subnormal(&da);
    df_normalize_subnormal(&db);

    p = mul128(df_sig(da), df_sig(db));

    /* normalize to 53 bits (top bit at 52) */
    {
        uint64_t sig;
        int e = da.exp + db.exp - 1023;
        int top;

        if (p.hi & 0x10000000000000ULL)
        {
            /* top bit at position 104 */
            sig = (p.hi << 20) | (p.lo >> 44);
            /* keep 54 bits for rounding: rebuild */
            {
                /* sig54 = (p.hi << 20) | (p.lo >> 44) is 54+? bits */
            }
            e += 53;
        }
        else if (p.hi & 0x08000000000000ULL)
        {
            sig = (p.hi << 21) | (p.lo >> 43);
            e += 52;
        }
        else
        {
            /* find top bit in p.hi */
            top = 52;
            while (!(p.hi & ((uint64_t)1 << top)))
                top--;
            sig = (p.hi << (52 - top)) | (p.lo >> (64 - (52 - top)));
            e += top - 51;
        }

        /* sig is now 54 bits (implicit at 53); round the dropped 70 bits */
        {
            uint64_t frac, guard, round_bit, sticky;
            /* dropped bits are the remaining low bits of the 128-bit product */
            uint64_t drop_hi, drop_lo;
            if (p.hi & 0x10000000000000ULL)
            {
                drop_hi = p.hi & 0x000FFFFFFFFFFFFFULL; /* 53 bits */
                drop_lo = p.lo & 0xFFFFFFFFFFFFF0000ULL; /* high 52 of lo */
            }
            else if (p.hi & 0x08000000000000ULL)
            {
                drop_hi = p.hi & 0x0007FFFFFFFFFFFFULL;
                drop_lo = p.lo;
            }
            else
            {
                top = 52;
                while (!(p.hi & ((uint64_t)1 << top)))
                    top--;
                {
                    int sh = 52 - top;
                    drop_hi = p.hi & (((uint64_t)1 << (52 - sh)) - 1);
                    (void)drop_hi;
                }
                /* generic path: recompute dropped from shift */
            }

            /* Simpler and robust: recompute the 107-bit significand and
               the dropped bits exactly via the three 32-bit products. */
            {
                uint64_t a_lo = df_sig(da) & 0xFFFFFFFFULL;
                uint64_t a_hi = df_sig(da) >> 32;
                uint64_t b_lo = df_sig(db) & 0xFFFFFFFFULL;
                uint64_t b_hi = df_sig(db) >> 32;
                uint64_t P0 = a_lo * b_lo;
                uint64_t P1 = a_lo * b_hi + a_hi * b_lo;
                uint64_t P2 = a_hi * b_hi;
                /* total 106-bit = P2*2^64 + P1*2^32 + P0 */
                uint64_t lo = P0 | ((P1 & 0xFFFFFFFFULL) << 32);
                uint64_t hi = P2 + (P1 >> 32) + (lo < P0 ? 1 : 0);

                /* normalize: find top bit of the 128-bit number */
                int t = 127;
                if (hi)
                {
                    t = 63;
                    while (!(hi & (1ULL << t)))
                        t--;
                    t += 64;
                }
                else
                {
                    t = 63;
                    while (!(lo & (1ULL << t)))
                        t--;
                }
                /* shift so top bit is at position 53 (54-bit sig) */
                {
                    int sh = t - 53;
                    uint64_t sig54, rest_hi, rest_lo;
                    if (sh <= 0)
                    {
                        /* t < 53: shift left */
                        int ls = -sh;
                        sig54 = ((hi << (32 + ls)) | (lo >> (32 - ls))) & 0x003FFFFFFFFFFFFFULL;
                        rest_hi = 0;
                        rest_lo = 0;
                    }
                    else if (sh < 64)
                    {
                        sig54 = (hi << (32 - sh + 32 - 32)); /* placeholder */
                        sig54 = (hi << (64 - sh)) | (lo >> sh);
                        sig54 &= 0x003FFFFFFFFFFFFFULL;
                        rest_lo = lo & (((uint64_t)1 << sh) - 1);
                        rest_hi = 0;
                    }
                    else
                    {
                        sig54 = (hi << (128 - sh - 64)) | (lo >> (sh - 64));
                        sig54 &= 0x003FFFFFFFFFFFFFULL;
                        rest_hi = hi & (((uint64_t)1 << (128 - sh)) - 1);
                        rest_lo = 0;
                    }
                    (void)rest_hi;
                    (void)rest_lo;

                    guard = (sig54 >> 53) & 1;
                    round_bit = (sig54 >> 52) & 1;
                    sticky = (sig54 & 0x001FFFFFFFFFFFFFULL) != 0
                             || ((sh < 64) && (rest_lo != 0))
                             || (rest_hi != 0);

                    sig54 &= 0x001FFFFFFFFFFFFFULL; /* keep 53 bits */
                    if (guard && (round_bit || sticky || (sig54 & 1)))
                    {
                        sig54++;
                    }
                    if (sig54 & 0x0020000000000000ULL)
                    {
                        sig54 >>= 1;
                        e++;
                    }
                    sig = sig54 & 0x001FFFFFFFFFFFFFULL;
                }
            }

            frac = (sig >> 1) & 0x000FFFFFFFFFFFFFULL;
            r.frac = frac;
            r.exp = e + 1023;
            (void)guard;
            (void)round_bit;
            (void)sticky;
            (void)drop_hi;
            (void)drop_lo;
        }
    }

    r.sign = da.sign ^ db.sign;

    if (r.exp <= 0)
    {
        int sh = 1 - r.exp;
        if (sh >= 64)
        {
            r.frac = 0;
            r.exp = 0;
        }
        else
        {
            r.frac >>= sh;
            r.exp = 0;
        }
    }
    else if (r.exp >= 2047)
    {
        r.exp = 2047;
        r.frac = 0;
    }

    return (uint64_t)(double)df_pack(r);
}

/* ------------------------------------------------------------------ */
/* double divide                                                       */
/* ------------------------------------------------------------------ */

uint64_t __divdf3(double a, double b)
{
    union
    {
        double d;
        uint64_t u;
    } ua, ub;
    df_t da, db, r;
    uint64_t fa, fb;
    uint64_t q;
    u128_t rem128;
    uint64_t r64;
    int e;

    ua.d = a;
    ub.d = b;
    da = df_unpack(ua.u);
    db = df_unpack(ub.u);

    if (df_is_zero(da))
    {
        r = da;
        if (df_is_zero(db))
        {
            r.exp = 2047;
            r.frac = 1; /* NaN */
        }
        return (uint64_t)(double)df_pack(r);
    }
    if (df_is_zero(db))
    {
        /* infinity */
        r.sign = da.sign ^ db.sign;
        r.exp = 2047;
        r.frac = 0;
        return (uint64_t)(double)df_pack(r);
    }

    df_normalize_subnormal(&da);
    df_normalize_subnormal(&db);

    fa = df_sig(da); /* 53 bits, top at 52 */
    fb = df_sig(db);
    e = da.exp - db.exp + 1023;

    /* q0 = (fa << 1) / fb : a 54/53 division giving up to 54 bits */
    {
        u128_t num = mul128(fa, 2);
        q = div128_64(num.hi, num.lo, fb);
    }

    /* remainder = fa*2 - q*fb (128-bit) */
    {
        u128_t prod = mul128(q, fb);
        u128_t num = mul128(fa, 2);
        /* rem = num - prod (both ~106 bits) */
        rem128.lo = num.lo - prod.lo;
        rem128.hi = num.hi - prod.hi - (rem128.lo < num.lo ? 1 : 0);
        if (cmp128(rem128.hi, rem128.lo, 0, 0) < 0)
        {
            /* negative remainder: subtract 1 from q and recompute */
            q--;
            prod = mul128(q, fb);
            rem128.lo = num.lo - prod.lo;
            rem128.hi = num.hi - prod.hi - (rem128.lo < num.lo ? 1 : 0);
        }
    }

    /* correction: q += rem / fb (at most 1 or 2) */
    q += div128_64(rem128.hi, rem128.lo, fb);

    /*
     * Now q is the correctly rounded-ish 54-bit quotient of
     * (fa*2)/fb.  The true result significand is q (54 bits, top at 53)
     * and its exponent is e-1 (because we multiplied fa by 2).
     */
    {
        int top;
        uint64_t sig;

        if (q & 0x0020000000000000ULL)
        {
            sig = q;
        }
        else if (q & 0x0010000000000000ULL)
        {
            sig = q << 1;
            e++;
        }
        else
        {
            top = 51;
            while (!(q & ((uint64_t)1 << top)))
                top--;
            {
                int sh = 53 - top;
                sig = q << sh;
                e += sh;
            }
        }

        /* sig has 54 bits (top at 53); drop the last bit with rounding.
           The dropped bit is the LSB of sig; the sticky part is the
           final remainder (rem / fb < 1 so nothing below). */
        {
            uint64_t guard = sig & 1;
            uint64_t sticky = (cmp128(rem128.hi, rem128.lo, 0, 0) > 0);
            sig >>= 1;
            if (guard && (sticky || (sig & 1)))
            {
                sig++;
                if (sig & 0x0020000000000000ULL)
                {
                    sig >>= 1;
                    e++;
                }
            }
        }

        r.frac = (sig >> 1) & 0x000FFFFFFFFFFFFFULL;
        r.exp = e;
    }

    r.sign = da.sign ^ db.sign;

    if (r.exp <= 0)
    {
        int sh = 1 - r.exp;
        if (sh >= 64)
        {
            r.frac = 0;
            r.exp = 0;
        }
        else
        {
            r.frac >>= sh;
            r.exp = 0;
        }
    }
    else if (r.exp >= 2047)
    {
        r.exp = 2047;
        r.frac = 0;
    }

    (void)r64;
    return (uint64_t)(double)df_pack(r);
}

