/* double comparisons (NaN treated as false for all, like typical C)   */
/* ------------------------------------------------------------------ */

static int df_cmp(uint64_t a, uint64_t b)
{
    df_t da, db;
    uint64_t ma, mb;
    int sa, sb;

    da = df_unpack(a);
    db = df_unpack(b);
    sa = da.sign;
    sb = db.sign;
    ma = a & 0x7FFFFFFFFFFFFFULL;
    mb = b & 0x7FFFFFFFFFFFFFULL;

    if (sa != sb)
        return sa ? -1 : 1;
    if (ma == mb)
        return 0;
    if (ma < mb)
        return sa ? 1 : -1;
    return sa ? -1 : 1;
}

