uint64_t __floatsidf(int32_t x)
{
    uint64_t v = (uint64_t)(int64_t)x;
    uint64_t sign, mag;
    int shift;
    uint64_t exp, frac;

    if (v == 0)
        return 0;
    sign = v >> 63;
    mag = sign ? ((uint64_t)(-(int64_t)x)) : (uint64_t)x;

    shift = 0;
    while (!(mag & (1ULL << (31 - shift))))
        shift++;

    exp = (uint64_t)(1023 + 31 - shift) << 52;
    frac = (mag << (52 - (31 - shift))) & 0x000FFFFFFFFFFFFFULL;

    return (sign << 63) | exp | frac;
}

int32_t __fixdfsi(double x)
{
    union
    {
        double d;
        uint64_t u;
    } ux;
    df_t da;
    int sign, e;
    uint64_t sig;
    int64_t result;

    ux.d = x;
    da = df_unpack(ux.u);
    sign = da.sign;
    e = da.exp;

    if (e == 0)
        return 0; /* subnormal: |x| < 2^-1022 */
    if (e > 1023 + 31)
        return sign ? (int32_t)0x80000000 : 0x7fffffff;

    sig = da.frac | 0x0010000000000000ULL;
    e -= 1023;

    if (e < 0)
    {
        int sh = 52 - e;
        result = sh < 64 ? ((int64_t)(sig >> sh)) : 0;
    }
    else if (e > 52)
    {
        return sign ? (int32_t)0x80000000 : 0x7fffffff;
    }
    else
    {
        result = (int64_t)(((sig << e) >> 52));
    }

    return sign ? (int32_t)(-result) : (int32_t)result;
}

uint32_t __fixunsdfsi(double x)
{
    union
    {
        double d;
        uint64_t u;
    } ux;
    df_t da;
    int e;
    uint64_t sig;

    ux.d = x;
    da = df_unpack(ux.u);
    e = da.exp;

    if (da.sign)
        return 0;
    if (e == 0)
        return 0;
    if (e > 1023 + 32)
        return 0xFFFFFFFFU;

    sig = da.frac | 0x0010000000000000ULL;
    e -= 1023;

    if (e < 0)
    {
        int sh = 52 - e;
        return (uint32_t)(sh < 64 ? (sig >> sh) : 0);
    }
    if (e > 52)
        return 0xFFFFFFFFU;
    return (uint32_t)((sig << e) >> 52);
}

/* float (binary32) helpers: implement via double for simplicity */

uint64_t __extendsfdf2(float x)
{
    union
    {
        float f;
        uint32_t u;
    } u;
    uint32_t v = (uint32_t)(u.f = x, u.u);
    uint32_t sign = (v >> 31) & 1;
    uint32_t exp = (v >> 23) & 0xFF;
    uint32_t frac = v & 0x007FFFFF;

    if (exp == 0)
    {
        if (frac == 0)
            return sign << 63;
        /* subnormal: normalize */
        {
            int shift = 0;
            while (!(frac & 0x00400000))
            {
                frac <<= 1;
                shift++;
            }
            frac &= 0x007FFFFF;
            return (sign << 63)
                | ((uint64_t)(1023 - 127 - shift) << 52)
                | ((uint64_t)frac << 29);
        }
    }
    return (sign << 63) | ((uint64_t)(exp - 127 + 1023) << 52)
         | ((uint64_t)frac << 29);
}

float __truncdfsf2(double x)
{
    union
    {
        double d;
        uint64_t u;
    } ux;
    df_t da;
    uint32_t sign, exp, frac;
    uint64_t sig, guard, sticky;
    int e;

    ux.d = x;
    da = df_unpack(ux.u);
    sign = da.sign;
    e = da.exp;

    if (e == 0)
    {
        /* subnormal or zero: result 0 (values this small underflow) */
        if (da.frac == 0)
        {
            union
            {
                float f;
                uint32_t u;
            } z;
            z.u = sign << 31;
            return z.f;
        }
        {
            int shift = 0;
            while (!(da.frac & 0x0010000000000000ULL))
            {
                da.frac <<= 1;
                shift++;
            }
            da.exp = 1 - shift;
            e = da.exp;
        }
    }

    e -= 1023;
    sig = da.frac | 0x0010000000000000ULL;
    e -= 22; /* we keep 24-bit significand for binary32 */

    if (e < 0)
    {
        int sh = -e;
        if (sh >= 24)
        {
            union
            {
                float f;
                uint32_t u;
            } z;
            z.u = sign << 31;
            return z.f;
        }
        sig >>= sh;
        e = 0;
        /* round */
    }
    else if (e > 254)
    {
        union
        {
            float f;
            uint32_t u;
        } inf;
        inf.u = (sign << 31) | 0x7F800000;
        return inf.f;
    }

    /* sig is 53 bits; we need 24 (top at 23) */
    {
        int sh = 53 - 24;
        guard = (sig >> sh) & 1;
        sticky = (sig & ((1ULL << sh) - 1)) != 0;
        sig >>= sh;
        if (guard && (sticky || (sig & 1)))
            sig++;
        if (sig & (1ULL << 24))
        {
            sig >>= 1;
            e++;
        }
    }

    {
        union
        {
            float f;
            uint32_t u;
        } r;
        uint32_t frac23 = (uint32_t)(sig & 0x007FFFFF);
        if (e < 0)
        {
            /* subnormal float */
            int sh = -e;
            if (sh >= 24)
            {
                r.u = sign << 31;
                return r.f;
            }
            frac23 = (uint32_t)(sig >> sh);
            r.u = (sign << 31) | frac23;
        }
        else
        {
            r.u = (sign << 31) | ((uint32_t)(e + 127) << 23) | frac23;
        }
        return r.f;
    }
}

