/*
 * mylib_fp.c - software IEEE-754 floating point helpers for the MIPS VM.
 *
 * Debian's cross libgcc.a is built with the HARD float ABI (its __adddf3
 * contains COP1 instructions like `add.d $f0,$f12,$f14`), which the
 * JavaScript VM cannot execute, and which would even be an ABI mismatch
 * (hard-float helpers read arguments from FPU registers while our
 * -msoft-float code passes them in integer registers).
 *
 * So we provide every soft-float helper the compiler may reference, in
 * pure integer code, with round-to-nearest-even binary64 semantics.
 *
 * All helpers are compiled with -msoft-float, so `double`/`float`
 * parameters and return values flow through integer registers ($a0-$a3,
 * $v0/$v1), which the VM executes natively.
 *
 * Conventions used below (binary64):
 *   v = A * 2^(E - 52)   where A is the 53-bit significand (top bit 52)
 *   E = biased exponent - 1023 (unbiased), A = frac | (1 << 52)
 */

#include <stdint.h>

typedef struct
{
    unsigned int sign;
    int exp;              /* biased exponent 0..2047 */
    uint64_t frac;        /* 52-bit fraction */
} df_t;

static df_t df_unpack(uint64_t v)
{
    df_t d;
    d.sign = (unsigned int)((v >> 63) & 1);
    d.exp = (int)((v >> 52) & 0x7FF);
    d.frac = v & 0x000FFFFFFFFFFFFFULL;
    return d;
}

static uint64_t df_pack(df_t d)
{
    return (d.sign << 63) | ((uint64_t)d.exp << 52) | d.frac;
}

static uint64_t df_sig(df_t d)
{
    return d.frac | 0x0010000000000000ULL;
}

static int df_is_zero(df_t d)
{
    return d.exp == 0 && d.frac == 0;
}

/* expand subnormal (exp==0) to a normalized form (exp may become <= 0) */
static void df_normalize_subnormal(df_t *d)
{
    int shift;

    if (d->exp != 0 || d->frac == 0)
        return;
    shift = 0;
    while (!(d->frac & 0x0010000000000000ULL))
    {
        d->frac <<= 1;
        shift++;
    }
    d->exp = 1 - shift;
}

/* 128-bit product of two 64-bit values */
typedef struct
{
    uint64_t hi;
    uint64_t lo;
} u128_t;

static u128_t mul128(uint64_t a, uint64_t b)
{
    u128_t r;
    uint64_t a_lo = a & 0xFFFFFFFFULL;
    uint64_t a_hi = a >> 32;
    uint64_t b_lo = b & 0xFFFFFFFFULL;
    uint64_t b_hi = b >> 32;

    uint64_t p0 = a_lo * b_lo;
    uint64_t p1 = a_lo * b_hi;
    uint64_t p2 = a_hi * b_lo;
    uint64_t p3 = a_hi * b_hi;

    uint64_t mid = (p0 >> 32) + (p1 & 0xFFFFFFFFULL) + (p2 & 0xFFFFFFFFULL);

    r.lo = (mid << 32) | (p0 & 0xFFFFFFFFULL);
    r.hi = p3 + (p1 >> 32) + (p2 >> 32) + (mid >> 32);
    return r;
}

/* 128-bit / 64-bit -> 64-bit quotient, floor (binary long division) */
static uint64_t div128_64(uint64_t hi, uint64_t lo, uint64_t d)
{
    uint64_t q = 0;
    uint64_t rem = 0;
    int i;

    if (d == 0)
        return 0;
    for (i = 63; i >= 0; i--)
    {
        rem = (rem << 1) | ((hi >> i) & 1);
        if (rem >= d)
        {
            rem -= d;
            q |= 1ULL << i;
        }
        rem = (rem << 1) | ((lo >> i) & 1);
        if (rem >= d)
        {
            rem -= d;
            q |= 1ULL << i;
        }
    }
    return q;
}

/* ------------------------------------------------------------------ */
/* double add / sub                                                    */
/* ------------------------------------------------------------------ */

static uint64_t df_add(uint64_t a_in, uint64_t b_in, int sub)
{
    df_t a, b, r;
    int same_sign;

    if (sub)
        b_in ^= (1ULL << 63);

    a = df_unpack(a_in);
    b = df_unpack(b_in);

    if (df_is_zero(a))
        return b_in;
    if (df_is_zero(b))
        return a_in;

    df_normalize_subnormal(&a);
    df_normalize_subnormal(&b);

    same_sign = (a.sign == b.sign);

    /* make sure a has the larger (or equal) exponent */
    if (a.exp < b.exp)
    {
        uint64_t t = a_in;
        a_in = b_in;
        b_in = t;
        a = df_unpack(a_in);
        b = df_unpack(b_in);
    }

    {
        int diff = a.exp - b.exp;
        uint64_t sa = df_sig(a);
        uint64_t sb = df_sig(b);
        uint64_t sig;
        int e = a.exp;
        int rsign;
        uint64_t dropped = 0;
        int has_dropped = 0;

        if (diff > 64)
        {
            /* b is far smaller than a's ulp: result is a (magnitude
               difference cannot affect rounding) */
            r = a;
            return df_pack(r);
        }

        if (diff > 0)
        {
            dropped = (sb >> (diff - 1)) & 1;             /* guard */
            if (diff >= 2)
                dropped |= (sb >> (diff - 2)) & 1;       /* round */
            dropped |= sb & (((uint64_t)1 << (diff - 1)) - 1); /* sticky */
            sb >>= diff;
            has_dropped = 1;
        }

        if (same_sign)
        {
            sig = sa + sb;
            rsign = a.sign;

            /* carry: 54-bit sig */
            if (sig & 0x0020000000000000ULL)
            {
                sig >>= 1;
                e++;
                if (has_dropped)
                    dropped >>= 1;
            }

            /* round to nearest, ties to even */
            if (has_dropped && (dropped & 1)
                && ((dropped >> 1) || (sig & 1)))
            {
                sig++;
                if (sig & 0x0020000000000000ULL)
                {
                    sig >>= 1;
                    e++;
                }
            }
        }
        else
        {
            /* subtraction of aligned integers: exact, no rounding */
            if (sa >= sb)
            {
                sig = sa - sb;
                rsign = a.sign;
            }
            else
            {
                sig = sb - sa;
                rsign = b.sign;
            }

            if (sig == 0)
            {
                r.sign = 0;
                r.exp = 0;
                r.frac = 0;
                return df_pack(r);
            }

            /* renormalize: top bit may be below 52 */
            {
                int t = 52;
                while (!(sig & ((uint64_t)1 << t)))
                    t--;
                {
                    int sh = 52 - t;
                    sig <<= sh;
                    e -= sh;
                }
            }
        }

        r.sign = rsign;
        r.exp = e;
        r.frac = (sig >> 1) & 0x000FFFFFFFFFFFFFULL;

        if (r.exp <= 0)
        {
            int sh = 1 - r.exp;
            if (sh >= 64)
            {
                r.frac = 0;
                r.exp = 0;
            }
            else
            {
                r.frac >>= sh;
                r.exp = 0;
            }
        }
        else if (r.exp >= 2047)
        {
            r.exp = 2047;
            r.frac = 0;
        }
    }

    return df_pack(r);
}

