/* ------------------------------------------------------------------ */
/* double multiply                                                     */
/*                                                                     */
/* a*b = P * 2^(t + ea + eb - 2150), P = A*B (<=106 bits),             */
/* t = top bit position of P.  E = t + ea + eb - 1127 (biased),        */
/* significand S54 = P >> (t-53) (54 bits, top bit 53).                */
/* ------------------------------------------------------------------ */

uint64_t __muldf3(double a, double b)
{
    union
    {
        double d;
        uint64_t u;
    } ua, ub;
    df_t da, db, r;
    u128_t p;
    int t, sh;
    uint64_t s54;
    uint64_t guard, sticky;

    ua.d = a;
    ub.d = b;
    da = df_unpack(ua.u);
    db = df_unpack(ub.u);

    if (df_is_zero(da) || df_is_zero(db))
    {
        /* 0 times anything: return signed zero (skip NaN nuances) */
        r.sign = da.sign ^ db.sign;
        r.exp = 0;
        r.frac = 0;
        return (uint64_t)(double)df_pack(r);
    }

    df_normalize_subnormal(&da);
    df_normalize_subnormal(&db);

    p = mul128(df_sig(da), df_sig(db));

    /* find top bit t of the 128-bit product */
    if (p.hi)
    {
        t = 63;
        while (!(p.hi & (1ULL << t)))
            t--;
        t += 64;
    }
    else
    {
        t = 63;
        while (!(p.lo & (1ULL << t)))
            t--;
    }

    sh = t - 53; /* 51 or 52 for normal products */
    s54 = (p.hi << (64 - sh)) | (p.lo >> sh);

    /* guard bit = bit t-54 of P, sticky = any bit below it */
    if (t - 54 < 64)
    {
        guard = (p.lo >> (t - 54)) & 1;
        sticky = (p.lo & (((uint64_t)1 << (t - 54)) - 1)) != 0;
    }
    else
    {
        guard = (p.hi >> (t - 54 - 64)) & 1;
        sticky = (p.hi & (((uint64_t)1 << (t - 54 - 64)) - 1)) != 0;
    }

    if (guard && (sticky || (s54 & 1)))
        s54++;

    {
        int e = t + da.exp + db.exp - 1127;

        if (s54 & 0x0040000000000000ULL)
        {
            /* rounding pushed it to 55 bits */
            s54 >>= 1;
            e++;
        }

        r.sign = da.sign ^ db.sign;
        r.exp = e;
        r.frac = (s54 >> 1) & 0x000FFFFFFFFFFFFFULL;

        if (r.exp <= 0)
        {
            int u = 1 - r.exp;
            if (u >= 64)
            {
                r.frac = 0;
                r.exp = 0;
            }
            else
            {
                r.frac >>= u;
                r.exp = 0;
            }
        }
        else if (r.exp >= 2047)
        {
            r.exp = 2047;
            r.frac = 0;
        }
    }

    return (uint64_t)(double)df_pack(r);
}

/* ------------------------------------------------------------------ */
/* double divide                                                       */
/*                                                                     */
/* a/b = (A/B) * 2^(ea-eb).  q54 = floor((A<<52)/B): a 54-bit          */
/* integer with top bit 51..53, remainder 0 <= rem < B.                */
/* Round q54 with rem, normalize: E = (52-t) + ea - eb + 1023.         */
/* ------------------------------------------------------------------ */

uint64_t __divdf3(double a, double b)
{
    union
    {
        double d;
        uint64_t u;
    } ua, ub;
    df_t da, db, r;
    uint64_t A, B;
    u128_t num, prod;
    uint64_t q54;
    uint64_t rem;
    int t, s;

    ua.d = a;
    ub.d = b;
    da = df_unpack(ua.u);
    db = df_unpack(ub.u);

    if (df_is_zero(db))
    {
        /* infinity (or NaN if a is zero) */
        r.sign = da.sign ^ db.sign;
        r.exp = 2047;
        r.frac = df_is_zero(da) ? 1 : 0;
        return (uint64_t)(double)df_pack(r);
    }
    if (df_is_zero(da))
    {
        r = da;
        return (uint64_t)(double)df_pack(r);
    }

    df_normalize_subnormal(&da);
    df_normalize_subnormal(&db);

    A = df_sig(da);
    B = df_sig(db);

    /* num = A << 52 (128-bit) */
    num.lo = (A & 0xFFFULL) << 52;
    num.hi = A >> 12;

    q54 = div128_64(num.hi, num.lo, B);

    /* rem = num - q54*B  (0 <= rem < B, so rem fits in 64 bits) */
    prod = mul128(q54, B);
    rem = num.lo - prod.lo;
    {
        uint64_t borrow = (rem < num.lo) ? 1 : 0;
        rem = num.hi - prod.hi - borrow; /* must be 0 */
    }

    /* round to nearest, ties to even */
    if (rem * 2 > B || (rem * 2 == B && (q54 & 1)))
        q54++;

    /* normalize q54 (top bit t in 51..53; q54 may hit 2^54 after rounding) */
    if (q54 >= (1ULL << 53))
    {
        t = (q54 & (1ULL << 53)) ? 53 : 54;
        if (t == 54)
        {
            q54 >>= 1;
            t = 53;
        }
    }
    else
    {
        t = 52;
        while (!(q54 & ((uint64_t)1 << t)))
            t--;
    }

    s = 52 - t;
    {
        int e = s + da.exp - db.exp + 1023;
        uint64_t sig = q54;
        if (s > 0)
            sig <<= s;
        else if (s < 0)
            sig >>= -s;

        r.sign = da.sign ^ db.sign;
        r.exp = e;
        r.frac = (sig >> 1) & 0x000FFFFFFFFFFFFFULL;

        if (r.exp <= 0)
        {
            int u = 1 - r.exp;
            if (u >= 64)
            {
                r.frac = 0;
                r.exp = 0;
            }
            else
            {
                r.frac >>= u;
                r.exp = 0;
            }
        }
        else if (r.exp >= 2047)
        {
            r.exp = 2047;
            r.frac = 0;
        }
    }

    return (uint64_t)(double)df_pack(r);
}

/* ------------------------------------------------------------------ */
/* double comparisons (NaN handled as "not less/greater", eq=0)        */
/* ------------------------------------------------------------------ */

static int df_cmp(uint64_t a, uint64_t b)
{
    uint64_t ma, mb;
    int sa, sb;

    sa = (int)((a >> 63) & 1);
    sb = (int)((b >> 63) & 1);
    ma = a & 0x7FFFFFFFFFFFFFULL;
    mb = b & 0x7FFFFFFFFFFFFFULL;

    if (ma == mb)
        return 0;
    if (sa != sb)
        return sa ? -1 : 1;
    if (ma < mb)
        return sa ? 1 : -1;
    return sa ? -1 : 1;
}

