/* float (binary32) helpers, implemented via binary64                  */
/* ------------------------------------------------------------------ */

uint64_t __extendsfdf2(float x)
{
    union
    {
        float f;
        uint32_t u;
    } u;
    uint32_t v, sign, exp, frac;

    u.f = x;
    v = u.u;
    sign = (v >> 31) & 1;
    exp = (v >> 23) & 0xFF;
    frac = v & 0x007FFFFF;

    if (exp == 0)
    {
        if (frac == 0)
            return (uint64_t)sign << 63;
        /* subnormal: value = frac * 2^-149; normalize (top bit -> 23) */
        {
            int k = 0;
            while (!(frac & 0x00400000))
            {
                frac <<= 1;
                k++;
            }
            /* unbiased E = -126 - k  => biased 897 - k */
            return (sign << 63) | ((uint64_t)(897 - k) << 52)
                 | ((uint64_t)frac << 29);
        }
    }
    /* unbiased E = exp - 127 => biased exp + 896 */
    return (sign << 63) | ((uint64_t)(exp + 896) << 52)
