float __truncdfsf2(double x)
{
    union
    {
        double d;
        uint64_t u;
    } ux;
    union
    {
        float f;
        uint32_t u;
    } r;
    df_t da;
    uint64_t A, a24;
    int eu; /* unbiased double exponent */

    ux.d = x;
    da = df_unpack(ux.u);

    if (df_is_zero(da))
    {
        r.u = (uint32_t)da.sign << 31;
        return r.f;
    }
    df_normalize_subnormal(&da);

    eu = da.exp - 1023 - 52; /* value = A * 2^eu, A 53-bit top@52 */
    A = da.frac | 0x0010000000000000ULL;

    /* a24 = A >> 29 (24 bits, top@23); same unbiased exponent eu */
    a24 = A >> 29;
    {
        uint64_t guard = (A >> 28) & 1;
        uint64_t sticky = (A & ((1ULL << 28) - 1)) != 0;
        if (guard && (sticky || (a24 & 1)))
            a24++;
        if (a24 & (1ULL << 24))
        {
            a24 >>= 1;
            eu++;
        }
