/*
 * mylib_bits.c - bit-cast helpers between FP values and integer words.
 *
 * At -O2 GCC on soft-float MIPS expresses double<->uint64 / float<->uint32
 * bit casts as calls to these libgcc functions (instead of raw word moves).
 * We implement them with volatile temporaries so the compiler cannot fold
 * the body back into a recursive helper call.  All code paths are plain
 * integer loads/stores, safe for the VM.
 *
 * Little-endian MIPS (mipsel): the low-address word of a double holds the
 * low 32 bits of the 64-bit pattern.
 */

#include <stdint.h>

uint64_t __floatundidf(double d)
{
    volatile uint32_t t[2];
    t[0] = *(uint32_t *)&d;
    t[1] = *(uint32_t *)((char *)&d + 4);
    return ((uint64_t)t[1] << 32) | (uint64_t)t[0];
}

double __fixunsdfdi(uint64_t u)
{
    double d;
    volatile uint32_t t[2];
    t[0] = (uint32_t)u;
    t[1] = (uint32_t)(u >> 32);
    *(uint32_t *)&d = t[0];
    *(uint32_t *)((char *)&d + 4) = t[1];
    return d;
}

uint32_t __floatundisf(float f)
{
    volatile uint32_t t;
    t = *(uint32_t *)&f;
    return t;
}

float __fixunssfdi(uint32_t u)
{
    float f;
    volatile uint32_t t;
    t = u;
    *(uint32_t *)&f = t;
    return f;
}

/*
 * mylib_bits.c - bit-cast helpers between FP values and integer words.
 *
 * At -O2 GCC on soft-float MIPS expresses double<->uint64 / float<->uint32
 * bit casts as calls to these libgcc functions (instead of raw word moves).
 * We implement them with volatile accesses so the compiler cannot fold the
 * body back into a recursive helper call.  All code paths are plain
 * integer loads/stores, safe for the VM.
 *
 * Little-endian MIPS (mipsel): the low-address word of a double holds the
 * low 32 bits of the 64-bit pattern.
 */

#include <stdint.h>

uint64_t __floatundidf(double d)
{
    volatile uint32_t t[2];
    t[0] = *(volatile uint32_t *)&d;
    t[1] = *(volatile uint32_t *)((char *)&d + 4);
    return ((uint64_t)t[1] << 32) | (uint64_t)t[0];
}

double __fixunsdfdi(uint64_t u)
{
    double d;
    volatile uint32_t t[2];
    t[0] = (uint32_t)u;
    t[1] = (uint32_t)(u >> 32);
    *(volatile uint32_t *)&d = t[0];
    *(volatile uint32_t *)((char *)&d + 4) = t[1];
    return d;
}

uint32_t __floatundisf(float f)
{
    volatile uint32_t t;
    t = *(volatile uint32_t *)&f;
    return t;
}

float __fixunssfdi(uint32_t u)
{
    float f;
    volatile uint32_t t;
    t = u;
    *(volatile uint32_t *)&f = t;
    return f;
}

