typedef struct { unsigned int start; unsigned int len; } span_t; // len: bit31 = used

static void __heap_init(void) {
    if (__heap_ready) return;
    __heap_ready = 1;
    __spans[0].start = 0;
    __spans[0].len = HEAP_BYTES / 4;      /* free */
    __nspans = 1;
