    i = __span_find(off);
    if (i < 0 || !(__spans[i].len & SPAN_USED)) return;
    /* mark free, then coalesce with adjacent free spans */
    __spans[i].len &= ~SPAN_USED;
    /* coalesce with next */
    while (i + 1 < __nspans && !(__spans[i+1].len & SPAN_USED)
