/*
 * link_mips.ld - linker script for doomgeneric_mips.
 *
 * The VM loads only .text, .data and .rodata at their link VMAs into a
 * flat word map (reads of .bss return 0).  Layout:
 *   .text   at 0x10000
 *   .rodata after .text
 *   .data   after .rodata
 *   .bss    after .data  (NOLOAD: the VM returns 0 for these addresses)
 *
 * .MIPS.abiflags (and .comment/.note) are discarded: they are irrelevant
 * for a static binary running in the VM, and placing them after the
 * 64MB .bss made the link fail due to VMA overlap.
 */

ENTRY(main)

SECTIONS
{
    . = 0x10000;

    .text : {
        *(.text)
        *(.text.*)
        *(.gnu.linkonce.text.*)
    }

    . = ALIGN(16);

    .rodata : {
        *(.rodata)
        *(.rodata.*)
        *(.gnu.linkonce.rodata.*)
        *(.eh_frame)
    }

    . = ALIGN(16);

    .data : {
        *(.data)
        *(.data.*)
        *(.gnu.linkonce.data.*)
    }

    . = ALIGN(16);

    .bss (NOLOAD) : {
        __bss_start = .;
        *(.bss)
        *(.bss.*)
        *(COMMON)
        __bss_end = .;
    }

    /DISCARD/ : {
        *(.MIPS.abiflags)
        *(.comment)
        *(.note.*)
        *(.eh_frame_hdr)
    }
}

