arguments.command:
cd /app && python3 - <<'EOF'
d = open('doom.wad','rb').read()
import struct
numlumps, dirofs = struct.unpack('<II', d[4:12])
lumps = []
for i in range(numlumps):
    off = dirofs + i*16
    fileoff, size = struct.unpack('<II', d[off:off+8])
    name = d[off+8:off+16]
    lumps.append((name, fileoff, size))

def sstr(b):
    i = b.find(b'\x00')
    return b[:i] if i >= 0 else b
def checknum(name):
    n = sstr(name).lower()
    for i,(x,f,s) in enumerate(lumps):
        if sstr(x).lower() == n:
            return i
    return -1
def getnum(name):
    i = checknum(name)
    if i < 0: raise SystemExit(f'W_GetNumForName: {sstr(name).decode()} not found!')
    return i

start = getnum(b'S_START') + 1
end = getnum(b'S_END') - 1
print('start:', start, 'end:', end)

import re
src = open('doomgeneric/doomgeneric/info.c').read()
m = re.search(r'char \*sprnames\[\] = \{(.*?)\};', src, re.S)
names = re.findall(r'"([A-Za-z0-9_]+)"', m.group(1))
print('num sprite names:', len(names))

MAXFRAME = 29
modifiedgame = 1
errors = []
for spritename in names:
    sprtemp = [[-1]*8 for _ in range(MAXFRAME)]
    rotate = [False]*MAXFRAME
    sn = spritename.encode()
    for l in range(start, end+1):
        n, f, s = lumps[l]
        if sstr(n[:4]).lower() != sn.lower():
            continue
        frame = n[4] - 65
        rotation = n[5] - 48
        patched = getnum(n) if modifiedgame else l
        fr, ro = frame, rotation
        if fr < 0 or fr >= MAXFRAME or ro > 8:
            errors.append(f'{spritename} lump {l} {sstr(n)}: bad frame/rot ({fr},{ro})'); continue
        if ro == 0:
            if rotate[fr]:
                errors.append(f'{spritename} lump {l} {sstr(n)}: rotations and a rot=0'); continue
            rotate[fr] = True
            for r in range(8): sprtemp[fr][r] = l
        else:
            if not rotate[fr]:
                errors.append(f'{spritename} lump {l} {sstr(n)}: has rotations and a rot=0 (frame {chr(65+fr)})'); continue
            rotate[fr] = True
            r2 = ro - 1
            if sprtemp[fr][r2] != -1:
                errors.append(f'{spritename} lump {l} {sstr(n)}: TWO LUMPS frame {chr(65+fr)} rot {chr(49+ro)} (prev {sprtemp[fr][r2]})')
            sprtemp[fr][r2] = l
        if n[6:7]:
            f2 = n[6] - 65
            r2 = n[7] - 48
            if f2 < 0 or f2 >= MAXFRAME or r2 > 8:
                errors.append(f'{spritename} lump {l} {sstr(n)}: bad flip ({f2},{r2})'); continue
            if r2 == 0:
                if rotate[f2]:
                    errors.append(f'{spritename} lump {l} {sstr(n)}: flip rot0 dup'); continue
                rotate[f2] = True
                for r in range(8): sprtemp[f2][r] = l
            else:
                if not rotate[f2]:
                    errors.append(f'{spritename} lump {l} {sstr(n)}: flip has rot=0 before (frame {chr(65+f2)})'); continue
                rotate[f2] = True
                r3 = r2 - 1
                if sprtemp[f2][r3] != -1:
                    errors.append(f'{spritename} lump {l} {sstr(n)}: FLIP TWO LUMPS frame {chr(65+f2)} rot {chr(49+r2)} (prev {sprtemp[f2][r3]})')
                sprtemp[f2][r3] = l
for e in errors[:40]: print('ERROR:', e)
print('total errors:', len(errors))
if not errors: print('WAD CLEAN - runtime bug must be in the ported string/loader code')
EOF

events.thought:
My simulation has a bug: after `if ro == 0: ... rotate[fr] = True`, then for the next lump with ro≠0: `if not rotate[fr]: error "has rotations and a rot=0"` — but the actual C code is:

```c
    if (rotation == 0)
    {
	// the lump should be used for all rotations
	if (sprtemp[frame].rotate == false)
	    I_Error (... "multip rot=0 lump" ...);
	if (sprtemp[frame].rotate == true)
	    I_Error (... "rotations and a rot=0 lump" ...);
	sprtemp[frame].rotate = false;   // <-- sets to FALSE!!
	for (r=0 ; r<8 ; r++) { sprtemp[frame].lump[r] = ...; }
	return;
    }
    if (sprtemp[frame].rotate == false)
	I_Error (... "rotations and a rot=0 lump" ...);
    sprtemp[frame].rotate = true;
```

**The rot=0 path sets `rotate = false` (not true)!** (The logic of this code: rotate==true means "has specific rotations"; a rot=0 lump means "no rotation" — it sets rotate=false, and then the single-rotation path errors out if rotate==false... no wait, that would mean that after a rot=0 lump, a single-rotation lump for the same frame would error with "has rotations and a rot=0 lump". Hmm, that's the reverse of what the message says... actually the original code is:

