**`vm.memory` is a flat word map: `memory[wordAddr]` (wordAddr is the byte address, indexed by address — `this.memory[wordAddr]` with wordAddr being the byte address (e.g., `addr` from lw/sw) — so it's an object keyed by 32-bit byte address, storing 32-bit little-endian words.** For byte dumps, reconstruct: byte at address A = (memory[A & ~3] >>> ((A & 3) * 8)) & 0xff.

Write /tmp/dump.js:

```js
const { MIPSVM, runElf } = require('/tmp/vmcore.js');
const data = runElf('/app/doomgeneric_mips');
const vm = new MIPSVM();
vm.memory = data.memory;

// Custom run loop identical to runProgram, but check for pc entering I_Error
vm.pc = data.entry_point >>> 0;
let count = 0;
let dumped = false;
while (1) {
  const instruction = vm.memory[vm.pc] || 0;
  const oldPc = vm.pc;
  vm.pc = (vm.pc + 4) >>> 0;
  const result = vm.runInstruction(instruction);
  count++;
  if (vm.pc != ((oldPc + 4) >>> 0)) {
    const newPc = vm.pc;
    vm.pc = ((oldPc + 8) >>> 0);
    const dsi = vm.memory[oldPc + 4] || 0;
    vm.runInstruction(dsi);
    vm.pc = newPc;
    count++;
  }
  if (vm.pc === 0x1f4f0) { dump everything; dumped = true; break; }
  if (result !== 0 || vm.pc === 0 || vm.pc === oldPc) break;
  if (count > 20000000) { console.log('too many'); break; }
}
```

