function b(a) { const w = vm.memory[a & ~3] || 0; return (w >>> ((a & 3) * 8)) & 0xff; }
function str8(a) {
  let s = '';
  for (let i = 0; i < 8; i++) {
    const c = b(a + i);
    s += c ? String.fromCharCode(c) : '\0';
  }
  return s;
}

