function u32(a) { return (vm.memory[a & ~3] || 0) >>> 0; }
function i32(a) { const v = u32(a); return v | 0; }
function b(a) { const w = vm.memory[a & ~3] || 0; return (w >>> ((a & 3) * 8)) & 0xff; }
function str8(a) { let s=''; for (let i=0;i<8;i++){const c=b(a+i); s += c?String.fromCharCode(c):'\0';} return s; }

const JAL_INSTALL = 0x040108ac; // jal 0x422b0

vm.pc = data.entry_point >>> 0;
let count = 0;
let calls = 0;
while (1) {
  const instruction = vm.memory[vm.pc] || 0;
  const oldPc = vm.pc;
  vm.pc = (vm.pc + 4) >>> 0;
  const result = vm.runInstruction(instruction);
  count++;
  if (instruction === JAL_INSTALL) {
    calls++;
    const fs = i32(0x8cb3c), ls = i32(0x8cb40);
    const regs = vm.registers;
    const a0 = (regs[4]>>>0)|0, a1=(regs[5]>>>0), a2=(regs[6]>>>0), a3=(regs[7]>>>0);
    const lp = u32(0xbb7c4);
    const nm = lp ? str8(lp + a0*28) : '???';
    if (calls <= 12 || (a1 === 0) || calls > 2000) {
      console.log(`call#${calls} pc=${oldPc.toString(16)} lump=${a0} frame=${a1} rot=${a2} flip=${a3} fs=${fs} ls=${ls} name=${nm}`);
    }
  }
  if (vm.pc !== ((oldPc + 4) >>> 0)) {
    const newPc = vm.pc;
    vm.pc = ((oldPc + 8) >>> 0);
    vm.runInstruction(vm.memory[oldPc + 4] || 0);
    vm.pc = newPc;
    count++;
  }
  if (vm.pc === 0x1f4f0) {
    console.log('hit I_Error after', count, 'instructions; total R_InstallSpriteLump calls:', calls);
    const regs = vm.registers;
    console.log('a0=0x'+(regs[4]>>>0).toString(16),'a1=0x'+(regs[5]>>>0).toString(16),'a2=0x'+(regs[6]>>>0).toString(16),'a3=0x'+(regs[7]>>>0).toString(16));
    console.log('firstspritelump=', i32(0x8cb3c), 'lastspritelump=', i32(0x8cb40));
    break;
  }
  if (result !== 0 || vm.pc === 0 || vm.pc === oldPc) {
    console.log('terminated early pc=0x'+vm.pc.toString(16), 'calls=', calls);
    break;
  }
  if (count > 40000000) { console.log('limit'); break; }
}
process.exit(0);

