function u32(a) { return (vm.memory[a & ~3] || 0) >>> 0; }
function i32(a) { const v = u32(a); return v | 0; }
function dumpSpr(label) {
  const words = [];
  for (let i = 0; i < 2; i++) words.push(u32(0xb8ad8 + i*4).toString(16));
  const regs = vm.registers;
  console.log(`${label}: word0=0x${u32(0xb8ad8).toString(16)} word1=0x${u32(0xb8adc).toString(16)} a0=0x${(regs[4]>>>0).toString(16)} v0=0x${(regs[2]>>>0).toString(16)} v1=0x${(regs[3]>>>0).toString(16)} s0=0x${(regs[16]>>>0).toString(16)}`);
}

vm.pc = data.entry_point >>> 0;
let count = 0;
