new = """    const __regs = new Array(32).fill(0);
    __regs[29] = 0x7FFFFFFC
    // Every register write is normalized to an unsigned 32-bit value.
    // Without this, the same 32-bit pattern (e.g. 0xFFFFFFFF = -1) can be
    // stored as a signed JS number (-1, from sign-extended loads/`|0`
    // results) or as an unsigned one (0xFFFFFFFF, from `>>>0` results),
    // and equality tests like BEQ/BNE (===/!==) misbehave.
    this.registers = new Proxy(__regs, {
      get: (t, p) => t[p],
      set: (t, p, v) => { t[p] = v >>> 0; return true; }
    });"""
assert old in s
s = s.replace(old, new)
open('vm.js','w').write(s)
print('vm.js patched')
EOF
