// Long-run trace: sample PC every 500k instructions, count read(0) syscalls
const { MIPSVM, runElf } = require('/tmp/vmcore.js');
const data = runElf('/app/doomgeneric_mips');
const vm = new MIPSVM();
vm.memory = data.memory;

let reads = 0, writes = 0;
vm.handleSyscall = (function (orig) {
  return function () {
    const num = this.registers[2] >>> 0;
    if (num === 0 && (this.fileDescriptors[this.registers[4] >>> 0] || 0) === 0) reads++;
    if (num === 1) writes++;
    return orig.call(this);
  };
})(vm.handleSyscall.bind(vm));

vm.pc = data.entry_point >>> 0;
let count = 0;
let lastSample = 0;
const t0 = Date.now();
while (1) {
  const instruction = vm.memory[vm.pc] || 0;
  const oldPc = vm.pc;
  vm.pc = (vm.pc + 4) >>> 0;
  const result = vm.runInstruction(instruction);
  count++;
  if (vm.pc !== ((oldPc + 4) >>> 0)) {
    const newPc = vm.pc;
    vm.pc = ((oldPc + 8) >>> 0);
    vm.runInstruction(vm.memory[oldPc + 4] || 0);
    vm.pc = newPc;
    count++;
  }
  if (count - lastSample >= 500000) {
    lastSample = count;
    const secs = ((Date.now() - t0) / 1000).toFixed(1);
    console.log(`t=${secs}s count=${count} pc=0x${vm.pc.toString(16)} reads=${reads} writes=${writes}`);
  }
  if (result !== 0 || vm.pc === 0 || vm.pc === oldPc) {
    console.log('terminated pc=0x' + vm.pc.toString(16), 'reads=', reads);
    break;
  }
  if (Date.now() - t0 > 90000) { console.log('time limit'); break; }
}
process.exit(0);

