// Inspect buffer pointers and cmap_to_fb a0 argument at runtime
const { MIPSVM, runElf } = require('/tmp/vmcore.js');
const data = runElf('/app/doomgeneric_mips');
const vm = new MIPSVM();
vm.memory = data.memory;

let sawCmap = 0;
let firstA0 = null, firstA1 = null, firstA2 = null;
const orig = MIPSVM.prototype.runInstruction;
vm.runInstruction = function (instruction) {
  // detect jal to cmap_to_fb (0x4f5d0): jal opcode 0x0C << 26 | (0x4f5d0>>2)
  const target = 0x0c013d74;
  if (instruction === target) {
    if (sawCmap < 3) {
      firstA0 = this.registers[4] >>> 0;
      firstA1 = this.registers[5] >>> 0;
      firstA2 = this.registers[6] >>> 0;
      console.log(`cmap_to_fb call #${sawCmap+1}: a0=0x${firstA0.toString(16)} a1=0x${firstA1.toString(16)} a2=${firstA2} pc_next=0x${(this.pc>>>0).toString(16)}`);
    }
    sawCmap++;
  }
  return orig.call(this, instruction);
};

vm.pc = data.entry_point >>> 0;
let count = 0;
const t0 = Date.now();
const mem = vm.memory;
function w(addr) { return (mem[addr] || 0) >>> 0; }
function bytes(addr, n) {
  let s = '';
  for (let i = 0; i < n; i++) {
    const b = (mem[addr + i] || 0) & 0xff;
    s += (b > 32 && b < 127 ? String.fromCharCode(b) : '.');
  }
  return s;
}
while (1) {
  const instruction = mem[vm.pc] || 0;
  const oldPc = vm.pc;
  vm.pc = (vm.pc + 4) >>> 0;
  const result = vm.runInstruction(instruction);
  count++;
  if (vm.pc !== ((oldPc + 4) >>> 0)) {
    const newPc = vm.pc;
    vm.pc = ((oldPc + 8) >>> 0);
    vm.runInstruction(mem[oldPc + 4] || 0);
    vm.pc = newPc;
    count++;
  }
  if (Date.now() - t0 > 15000) {
    console.log('--- at t=15s count=', count);
    console.log('I_VideoBuffer var @0xbb98c = 0x' + w(0xbb98c).toString(16));
    console.log('DG_ScreenBuffer var @0xbbdd0 = 0x' + w(0xbbdd0).toString(16));
    console.log('mystery var @0xbd5d0 = 0x' + w(0xbd5d0).toString(16));
    const ivb = w(0xbb98c), dgb = w(0xbbdd0), my = w(0xbd5d0);
    if (ivb) console.log('I_VideoBuffer content: ' + bytes(ivb, 64));
    if (dgb) console.log('DG_ScreenBuffer content: ' + bytes(dgb, 64));
    if (my) console.log('0xbd5d0 target content: ' + bytes(my, 64));
    break;
  }
  if (result !== 0 || vm.pc === 0) { console.log('terminated'); break; }
}
process.exit(0);

