// Trace first pixel's full instruction sequence inside cmap_to_fb call #2
const { MIPSVM, runElf } = require('/tmp/vmcore.js');
const data = runElf('/app/doomgeneric_mips');
const vm = new MIPSVM();
vm.memory = data.memory;

const JAL_CMAP = 0x0c013d74;
let calls = 0, tracing = false, ins = 0;
const R0 = MIPSVM.prototype.runInstruction;
vm.runInstruction = function (instruction) {
  const pc = this.pc - 4;
  if (instruction === JAL_CMAP) { calls++; if (calls === 2) tracing = true; }
  if (tracing) {
    if (pc === 0x4f6a8 && ins > 50) { tracing = false; console.log('--- end of first pixel after', ins, 'steps'); process.exit(0); }
    if (ins < 80) {
      console.log(`${String(ins).padStart(3)} pc=0x${pc.toString(16).padStart(6)} ins=0x${instruction.toString(16).padStart(8)} a0=0x${(this.registers[4]>>>0).toString(16)} v1=${this.registers[5]>>>0} a3=${this.registers[7]>>>0} t1=0x${(this.registers[9]>>>0).toString(16)}`);
    }
    ins++;
  }
  return R0.call(this, instruction);
};

vm.pc = data.entry_point >>> 0;
let count = 0;
const mem = vm.memory;
while (1) {
  const instruction = mem[vm.pc] || 0;
  const oldPc = vm.pc;
  vm.pc = (vm.pc + 4) >>> 0;
  const result = vm.runInstruction(instruction);
  count++;
  if (vm.pc !== ((oldPc + 4) >>> 0)) {
    const newPc = vm.pc;
    vm.pc = ((oldPc + 8) >>> 0);
    vm.runInstruction(mem[oldPc + 4] || 0);
    vm.pc = newPc;
    count++;
  }
  if (result !== 0 || vm.pc === 0) { console.log('terminated'); process.exit(0); }
  if (count > 300000000) { console.log('limit'); process.exit(0); }
}

