// Trace every instruction in I_FinishUpdate loop region 0x4f93c-0x4f99c, first row
const { MIPSVM, runElf } = require('/tmp/vmcore.js');
const data = runElf('/app/doomgeneric_mips');
const vm = new MIPSVM();
vm.memory = data.memory;
const JAL_CMAP = 0x0c013d74;
let inCall = 0, steps = 0, stop = false;
const R0 = MIPSVM.prototype.runInstruction;
vm.runInstruction = function (instruction) {
  const pc = this.pc - 4;
  if (instruction === JAL_CMAP) inCall++;
  // track while inside first cmap call + after, until second row starts (s0 advanced twice)
  if (!stop && inCall >= 1 && inCall <= 2 && pc >= 0x4f940 && pc <= 0x4f998) {
    const r = this.registers;
    console.log(`s5=0x${(r[21]>>>0).toString(16)} s3=0x${(r[19]>>>0).toString(16)} s0=0x${(r[16]>>>0).toString(16)} s6=${r[22]>>>0} v1=0x${(r[3]>>>0).toString(16)} pc=0x${pc.toString(16)} ins=0x${instruction.toString(16)}`);
    steps++;
    if (steps > 60) stop = true;
  }
  return R0.call(this, instruction);
};
vm.pc = data.entry_point >>> 0;
let count = 0;
const mem = vm.memory;
while (1) {
  const instruction = mem[vm.pc] || 0;
  const oldPc = vm.pc;
  vm.pc = (vm.pc + 4) >>> 0;
  const result = vm.runInstruction(instruction);
  count++;
  if (vm.pc !== ((oldPc + 4) >>> 0)) {
    const newPc = vm.pc;
    vm.pc = ((oldPc + 8) >>> 0);
    vm.runInstruction(mem[oldPc + 4] || 0);
    vm.pc = newPc;
    count++;
  }
  if (stop) { console.log('--- done tracing'); break; }
  if (result !== 0 || vm.pc === 0) { console.log('terminated'); break; }
  if (count > 300000000) { console.log('limit'); break; }
}
process.exit(0);

